quests[29919] = { id = 29919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great Minds Drink Alike", description = "Hello again, {name}. What is this, the fourth time we've run into one another already?\n\nSay... my keg is quickly becoming quite empty. I've heard mention of a brewery to the southwest, and that's where we're headed. Care to join us?", sourceObjective = "Escort Chen Stormstout and Li Li to the brewery in the southwest.", completion = "If yer lookin' fer beer, you came to the right place, neighbor.\n\nJust, ah... excuse the mess. Had me a bit of a problem with virmen the last few days.", sourceObjectiveStatus = "unverified-source-field" }
quests[29920] = { id = 29920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Permission", description = "My love, Lo, tried to get permission to marry me from the pandriarchs. Though they have passed beyond, their favor would carry a lot of weight.\n\nThing is, they are spirits, and none of the gifts or tributes we brought impress them. To win their favor they claimed that either Lo or a champion must defeat them in single combat.\n\nLo is a good man, but not a fighter.\n\nWould you be our champion?", sourceObjective = "Challenge and defeat Pandriarch Goldendraft, Pandriarch Windfur, and Pandriarch Bramblestaff.", progress = "Each of the pandriarchs earned their reputation in life and retained them afterward.  I can't even imagine how you will defeat them.", completion = "They... they agreed?! Fantastic! Thank you so much! With their blessing we can be the happiest pandaren in all the land!\n\nPlease, take this. We meant it to be a tribute for the pandriarchs but they didn't seem interested.", sourceObjectiveStatus = "unverified-source-field" }
quests[29922] = { id = 29922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Wisdom", description = "Lorewalker Cho came by and asked for you while you were gone.\n\nHe needs your assistance urgently in the town of Dawn's Blossom to the north. For what reason, he did not say.\n\nSpeak to Kitemaster Ut-Nam. He would be happy to send you there.", sourceObjective = "Speak to Kitemaster Ut-Nam and get a ride to Dawn's Blossom.", completion = "Your deeds have sparked a long forgotten memory I have of an ancient prophecy. This deserves investigation.\n\nIn order to investigate, I need jade though. I have instructed Toya to gather as much as he can find and give it to you when he is done. Bring it to me and we will see about deciphering the ancient \"Emperor's Omen.\"\n\nWhile he gathers the jade, feel free to explore. You may find the people of this town are in need of a person of your caliber.", sourceObjectiveStatus = "unverified-source-field" }
quests[29924] = { id = 29924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Kher Shan", description = "Kher Shan is one big dooker.\n\nGrooked all my sons! Ick Ick, Nab Nab, Eet Eet, Bitty Bitty, and the others I can't remember.\n\nWikket wanna help hozen? Go grook Kher Shan!\n\nThe dooker's over there.\n\n<Nibi Nibi points to the east.>", sourceObjective = "Kill Kher Shan in Tigers' Wood.", sourceObjectiveStatus = "unverified-source-field" }
quests[29925] = { id = 29925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All We Can Spare", description = "Alright, I called in every favor I could. Here's what we got.\n\nCho must be on to something big!\n\nLemme know when you're ready to go see him - I got a ride all prepared for ya.", sourceObjective = "Deliver the Scavenged Jade to Lorewalker Cho at Emperor's Omen. Speak with Toya in Dawn's Blossom for a ride.", progress = "Ah, hello again, {name}! You received my message, then?", completion = "I knew Toya would come through for me!\n\nHe can get anything, you know.", sourceObjectiveStatus = "unverified-source-field" }
quests[29926] = { id = 29926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calamity Jade", description = "You ever seen a shale spider, {class}? Usually harmless, just creepin' around eatin' rocks, but they got a taste for jade like cubs on candy. The boys call 'em \"nibblers.\"\n\nA few days back, we tunneled into a huge nest of these critters. They spilled out into the mines and went crazy, chewed up damn near everything in sight - including some of the boys.\n\nYou get in there and clear 'em out, and we got plenty of jade to spare. The quarry is directly west of here.", sourceObjective = "Slay 12 Greenstone Nibblers and 6 Greenstone Gorgers at the Greenstone Quarry.", completion = "Well I'll be... you actually did it!\n\nYou lookin' for a more permanent job, buddy? I could use a bruiser like you around full-time!", sourceObjectiveStatus = "unverified-source-field" }
quests[29927] = { id = 29927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mann's Man", description = "<For once, the foreman lowers her voice.>\n\nLook, this ain't easy... I got another favor to ask. My idiot husband, Hao, is a shift lead down at the quarry. I told him not to go back, that it was too dangerous, but he's as stubborn as a hozen and twice as stupid. Says the boys need him around for \"moral support.\"\n\n<Mann sneers.>\n\nWhat about my moral support?! What am I gonna do if that idiot dies?!\n\nPlease... keep an eye out for him. Tell him to come home.\n\n<Her eyes soften before she turns away.>", sourceObjective = "Locate Hao Mann at the Greenstone Quarry.", completion = "<Hao looks up at you, struggling to pull himself from the rubble.>\n\nNo, no. I got it. HNNGHHH!!\n\nOkay, maybe I don't got it.", sourceObjectiveStatus = "unverified-source-field" }
quests[29928] = { id = 29928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Have No Jade And I Must Scream", description = "Our whole jade supply line has fallen apart. The mines are a death trap, morale is historically low, and - as if that weren't bad enough - the mason's quarter has been overrun by wood sprites!\n\nNow even the plants are out to ruin me!\n\nYou need jade so badly, you can follow the road southwest to the mason's quarter and get it from those glorified chopsticks yourself.", sourceObjective = "Recover 15 Chunks of Jade from Puckish Sprites around the Greenstone Mason's Quarter.", progress = "<Mann looks at you expectantly, eyes wide and nostrils flared.>", completion = "Catch? They were playin' CATCH with my product?!\n\nI hope you showed those walkin' toothpicks a thing or two.\n\nYou know, maybe you ain't a cub after all. I've been lookin' for some muscle to help out with my problem at the quarry.\n\nAnd judgin' by the size of the Lorewalker's restoration project here, I think you'll need a lot more jade.", sourceObjectiveStatus = "unverified-source-field" }
quests[29929] = { id = 29929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapped!", description = "<Hao struggles against the rubble with all his might.>\n\nHNNNGHHH!!\n\nLet me guess: my wife sent you? Imagine that, my delicate little snow lily all worried. Ha ha! She's always frettin' over me. Look--HNNGHH!!!--it'll take more than a little--HNNGGHHH!!--cave-in to keep ol' Hao down.\n\nSome o' the boys, on the other hand, are in trouble. Help 'em out if you find any, will ya? I'll be fine.\n\nReally.", sourceObjective = "Free 8 Greenstone Miners in the Greenstone Quarry.", completion = "<Hao lets out a hearty laugh.>\n\nI seen 'em come runnin' out o' there like ol' Kher Shan himself were givin' chase.", sourceObjectiveStatus = "unverified-source-field" }
quests[29930] = { id = 29930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Mined Is Yours", description = "Aw'right, so you need jade, do ya? I'd say we owe you at least that - we got plenty in the quarry, and thanks to yer help we should be back on schedule in no time.\n\nI should probably get back to the wife, so let's you and me take this cart o' the good stuff straight to her.\n\nNow, I ain't never met no {race} t'were too big for me to pull in a wagon. You climb on the back there and let ol' Hao do the legwork.", sourceObjective = "Board the jade cart and ride with Hao back to Emperor's Omen.", progress = "Well? Where's Hao?\n\nDon't tell me you couldn't find him...", completion = "You did it! You brought my honey-bear back!\n\nOh thank you, {name}! Thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[29931] = { id = 29931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Serpent's Heart", description = "You've done great here, kid. Thanks to you, we have quite a bit of extra jade, and I know just the someone who could use it.\n\nMy friend Foreman Raike is running the great statue project at the Serpent's Heart.\n\nBring a shipment of extra jade to him, and tell him his old friend Mann says hello. He'll be eagerly waiting your arrival.", sourceObjective = "Speak to Foreman Raike at the Serpent's Heart in the Jade Forest.", completion = "Am I seeing this right? A whole shipment of pure, high quality uncut jade?\n\nThank goodness. I knew Foreman Mann would come through for us.\n\nOh and you too. Thanks for bringing it by.", sourceObjectiveStatus = "unverified-source-field" }
quests[29932] = { id = 29932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of the Jade Serpent", description = "You've done us a huge favor here, traveler.\n\nNow that we have enough jade to complete the statue, we should send word of our progress to Yu'Lon, the Jade Serpent.\n\nWhen you arrive, speak to Elder Sage Wind-Yi outside the entrance to the Temple of the Jade Serpent.\n\nIf you wish to speed your journey, speak to Kitemaster Shoku. I'm sure he can spare an extra kite for you.", sourceObjective = "Speak to Elder Sage Wind-Yi outside the entrance to the Temple of the Jade Serpent. Speak to Kitemaster Shoku for a kite ride to the temple.", progress = "Yes?", completion = "You bring news from the Serpent's Spine?\n\n<The Elder Sage patiently listens to your tale of what occurred at the Jade Mines and at the large jade statue.>\n\nThank you for coming all this way, stranger. However, I cannot allow you to speak to the Jade Serpent right now.\n\nThe ancient one is very busy, and as you can see, is not here at the moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[29933] = { id = 29933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bees' Knees", description = "You really hozen friend, wikket? Let's see, hmm?\n\nHozen at Grookin' Hill all outta slicky bait. Tigerflies' legs stay twitchy in water - make best bait!\n\nBo Bo sick from stings. Wikket get bait and take to Grookin.", sourceObjective = "Collect 30 Bug Legs from Tigerflies in Tigers' Wood.", progress = "Slicky food!", completion = "Woot! Woot! Wikket da Ook Dook!", sourceObjectiveStatus = "unverified-source-field" }
quests[29934] = { id = 29934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Ravenholdt", description = "If the egg is in Ravenholdt Manor, we can't risk torching it in an all-out assault. I'll need someone slippery to get in there and find out for sure.\n\nThat's you, {name}.\n\nMostrasz will help you infiltrate the compound. Speak to him just outside and fly to Ravenholdt together. Good luck!", sourceObjective = "Speak to Mostrasz at the Vermillion Redoubt and fly to Ravenholdt Manor together.", progress = "So, are you ready to do some spying?", completion = "So far so good. Are you ready to do some spying?", sourceObjectiveStatus = "unverified-source-field" }
quests[29935] = { id = 29935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders are Orders", description = "Hmm, maybe wikket not so bad after all!\n\nOther baldskins not nice to hozen.\n\nHozen take this from bad wikkets!\n\nAll wikket loot goes to Kah Kah - Chief's orders!\n\nHere, wikket. You take it. Kah Kah will want to meet new hozen friend.\n\nHis camp south at Grookin Hill.", sourceObjective = "Bring the Alliance Orders to Chief Kah Kah at Grookin.\n\nProvided item:", completion = "Hmm.\n\nMean wikkets fighting with nice wikkets?\n\nHozen fight mean wikkets too!", sourceObjectiveStatus = "unverified-source-field" }
quests[29936] = { id = 29936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instant Messaging", description = "Welcome, wikket! Me Kah Kah - chief of Grookin Hill hozen.\n\nDook Ookem wanted to be chief, but good wikket grook him good - big gift to Kah Kah.\n\nHozen has gift for good wikket too. Gift come from great crash. Hozen keep it safe for wikket.", sourceObjective = "Use the Hellscream's Fist Signal Flare near Chief Kah Kah at Grookin Hill.", completion = "Impressive work, {name}.\n\nIt had not occurred to me that we might somehow befriend these creatures.\n\nWith their acceptance, we can now turn our attention to more important matters.", sourceObjectiveStatus = "unverified-source-field" }
quests[29937] = { id = 29937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furious Fowl", description = "So these guys like fish, huh? Well how about we finish what you started and make them LOVE us?\n\nI've still got some explosive powder from the wreck, just need something to attract the fish.\n\nGuts is sure to do the trick - never fails. I saw some birds flyin' around south of town.\n\nWell? Whatcha waitin' for?", sourceObjective = "Collect 6 Fistfuls of Bird Guts from Bloodtalons in Dookin' Grounds.", progress = "You didn't touch that stuff with your hands did ya?", completion = "Yeah!\n\nNow that's the stuff. Just you wait and see...", sourceObjectiveStatus = "unverified-source-field" }
quests[29938] = { id = 29938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends and Foes", description = "These ookin' Jinyu grookin Kah Kah's nephews!\n\nWikket once kill many hozen. Now wikket kill many jinyu.", sourceObjective = "Kill 7 Riverstride Jinyu at the Slicky Stream.", sourceObjectiveStatus = "unverified-source-field" }
quests[29939] = { id = 29939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boom Bait", description = "There. I've plastered your bird guts over my explosives.\n\nI call 'em Gut Bombs, patent pending.\n\nSince you made friends with these fellas, how about you do the honors?\n\nJust light the fuse and throw 'em down by the shoreline!", sourceObjective = "Use the Gut Bombs at Murky Bank and collect 5 Exploded Slickies.", progress = "I have yet to face a crisis that couldn't be fixed with dynamite.", completion = "We've just revolutionized how these cretins.. err, hozen, feed themselves.\n\nThey'll never be the same!", sourceObjectiveStatus = "unverified-source-field" }
quests[29940] = { id = 29940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking a Crop", description = "Alright, fine. I DON'T have everything under control here. I spent all morning fighting off virmen. I managed to clear them off of my property, but they got away with some of my crops.\n\nThey took them down to the river, to the south. I have no idea what they're doing with them, but it's probably not eating them.\n\nIf my father wants his delivery now, I'm going to need some help getting those crops back. Could you help me out?", sourceObjective = "Obtain 5 Stolen Turnips and 5 Stolen Watermelons.", progress = "If my father wants his vegetables, I'm going to need your help.", completion = "Perfect.\n\n<Ang surveys the bruised turnips and the soggy watermelons.>\n\nWhat were they DOING down there!?", sourceObjectiveStatus = "unverified-source-field" }
quests[29941] = { id = 29941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beyond the Horizon", description = "I recognize all you've managed to do here, {class}. My report to the Warchief will include an account of your deeds.\n\nBut there's no time to rest!\n\nThis land must be charted and prepared for Horde settlement. I've already selected an away team to do just that.\n\nFind them before they grow comfortable here. Inform them of their mission, and try to convince your new friends to send along one of their own to serve as a guide.\n\nYou'll be staying here with me. We have preparations to make.", sourceObjective = "Speak to Shokia, Sergeant Gorrok, Shademaster Kiryn, and Chief Kah Kah", progress = "Has the away team been dispatched, {name}?", completion = "Good work {name}.\n\nThe away team you assembled has departed.\n\nI hope Gorrok had the sense to change out of that ragged red shirt. I admire his patriotism, but he's had it on since we left Orgrimmar.\n\nThey won't be surprising anyone if he's wearing it...", sourceObjectiveStatus = "unverified-source-field" }
quests[29942] = { id = 29942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silly Wikket, Slickies are for Hozen", description = "You think hozen crazy, wikket? Wait til you see hozen with no slickies!\n\nNot enough slickies for hozen and wikkets.\n\nSnappers! Hozen hate them ookin' snappers. Wikkets can eat all the snappers!\n\n<Eekle Eekle points to the south.>", sourceObjective = "Collect 4 Snapper Steaks from the Murky Bank", progress = "Wikket grook all them ookin' snappers?", completion = "Now everybody got grub! Great hozen wisdom in Eekle Eekle.\n\nMaybe Eekle Eekle become Chieftain someday...", sourceObjectiveStatus = "unverified-source-field" }
quests[29943] = { id = 29943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guerrillas in our Midst", description = "Prince Anduin Wrynn. The very son of our enemy's king! Fortune has smiled on the Horde once again, {name}.\n\nBut there's another side of this coin. We'd be naive to think the child was left alone.\n\nAny Alliance scum within sight of this land must be searching desperately for their precious princeling.\n\nYou and I are going to scour the area and root out his would-be rescuers.", sourceObjective = "Kill 8 Alliance Infiltrators near the Scenic Overlook.", progress = "I love the sound of screaming Alliance in the morning.", completion = "Yes!\n\nBy Thrall's bloodied fist, I've missed hunting Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[29944] = { id = 29944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leaders Among Breeders", description = "Before any kegs are tapped, we have work to do. These virmen are no different than the virmen on the Wandering Isle... a nuisance that breeds as fast as the rabbits they resemble.\n\nSure, we could kill every last virmen we find, but what's the point in needless bloodshed? Let's just take out their alphas, and they'll slow down with their... reproduction.", sourceObjective = "Slay Aiyu the Skillet, Jinanya the Clawblade, and Frenzyhop.", progress = "The virmen here have strange habits. Stranger names.", completion = "<Chen nods.>\n\nGood work, {name}. You're not bad in combat.\n\nWhat do you say we team up for the next part?", sourceObjectiveStatus = "unverified-source-field" }
quests[29945] = { id = 29945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yellow and Red Make Orange", description = "Uncle Chen says we're going to help this guy out with his virmen problem. Fine by me! I LOVE messing with virmen.\n\nHere's the plan: we're going to paint some turnips orange, and then we'll try to convince the virmen that they're carrots.\n\nThis can only end in comedy.\n\nI'll gather turnips. You find something that we can use to make edible orange paint.", sourceObjective = "Obtain 10 Meadow Marigolds and 40 Vials of Animal Blood.", progress = "You have the stuff ready for the paint? I went ahead and gathered some turnips.", completion = "Whoah, whoah, WHOAH! You brought back BLOOD? I guess I should have looked around for a half second before I asked you to bring me something red.\n\nYeesh!\n\n<Li Li turns back to the ingredients, spends a moment crushing the flower petals, and then mixes in some of the blood.>\n\n<She begins to giggle.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29946] = { id = 29946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warren-Mother", description = "We've dealt with the alpha males. Now, the alpha female.\n\nVirmen aren't terribly selective when it comes to breeding, but most broods will still have a dominant mother figure. She's usually bigger, meaner, and tougher than anyone else in the brood.\n\nYou know, I wouldn't mind testing my skills against a warren-mother. Mind if I fight alongside you?", sourceObjective = "Defeat Chufa, the Twitchheel Warren-Mother.", progress = "Ready when you are, {name}.\n\nYou go ahead. I'll meet you down there.", completion = "That should take care of the virmen for a few weeks, at least. Enough time for Mudmug to get out a few good batches of beer, uninterrupted.\n\nAnd isn't that what's really important?", sourceObjectiveStatus = "unverified-source-field" }
quests[29947] = { id = 29947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crouching Carrot, Hidden Turnip", description = "Uncle Chen's still got his eye on me, which means I won't be wandering off any time soon. I guess it's up to you to take these turnips... I mean, \"carrots\"... into the Twisted Warren and deliver them for me.\n\nIt should be pretty simple. Just toss the vegetables in front of virmen, then watch their reaction when they find out it's really a turnip!", sourceObjective = "Toss Orange-Colored Turnips in front of 12 Twitchheel Hoarders.", progress = "Go, torment those virmen, {name}!", completion = "Bah ha hah haaaa! I love messing with virmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29948] = { id = 29948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieves to the Core", description = "You and that Chen fellow are good people, helpin' out with the virmen like you are. I don't like to ask for favors, but I ain't gonna turn 'em away, either.\n\nWhile you're out there puttin' the hurt to those rabbit-men, you wouldn't mind keepin' an eye out for some bags o' hops, would ya? I'm pretty sure they lifted 'em last night.\n\nProbably usin' em for pillows, knowin' how they are.", sourceObjective = "Recover 6 Stolen Sacks of Hops from the Twisted Warren.", progress = "I done told those virmen to stay off my land.", completion = "Aww, thank ya kindly, sir. You're a real gentleman.", sourceObjectiveStatus = "unverified-source-field" }
quests[29949] = { id = 29949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy", description = "I'd say we've earned our reward. I can't wait to taste what Mudmug's been brewing.", sourceObjective = "Have a drink with Chen, Li Li, and Mudmug.", completion = "I know Uncle Chen's coming back. I'm not worried.\n\nActually, this is probably my big chance to finally explore Pandaria! No fat uncle tying me down!", sourceObjectiveStatus = "unverified-source-field" }
quests[29950] = { id = 29950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Li Li's Day Off", description = "Uncle Chen asked me not to get into any fights while he was away... but that doesn't mean I can't go exploring. Finally, a chance to look around Pandaria without stopping every forty-seven steps for another rest!\n\nYou want to come with me? I'll bet there's all kinds of cool places we can visit, not too far away from here.", sourceObjective = "Bring Li Li to the Silken Fields, New Cifera, and Huangtze Falls.", progress = "You ready to go out yet?", completion = "That was great! You and I should go exploring again sometime.\n\nAnd it looks like we finished before Uncle Chen got back, too. Perfect.", sourceObjectiveStatus = "unverified-source-field" }
quests[29951] = { id = 29951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muddy Water", description = "While you're just hangin' around, I might as well get you involved in my whole beer-makin' \"process\". Ain't much of a process, really... I just mix all the stuff together and wait.\n\nYou probably heard - I like to use the muddy water from the riverbanks, to the south. Would you mind fillin' up this flask with that water and bringin' it back? I'll start gettin' the hops and barley all ready.", sourceObjective = "Use Mudmug's Vial to gather muddy water.", progress = "I knowed you for a friend as soon as I seen you.", completion = "You done good, {name}. You done good.", sourceObjectiveStatus = "unverified-source-field" }
quests[29952] = { id = 29952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Dreams", description = "Yes, I found the Stormstout Brewery... although I didn't exactly get the warm reception I expected.\n\n<Chen pours himself a mug of ale.>\n\nDo you want to hear the story?", sourceObjective = "Speak with Chen Stormstout and listen to his story.", progress = "...", completion = "Maybe I wasn't meant to settle down anyhow.", sourceObjectiveStatus = "unverified-source-field" }
quests[29966] = { id = 29966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Down the House", description = "Look, {name}!\n\nThese Alliance dogs built a camp up on the ridge.\n\nHere, take my grog. Let's make a fire they can see from Stormwind!\n\nFor the Horde!", sourceObjective = "Use Nazgrim's Grog to destroy the Alliance Camp atop the Scenic Overlook.", completion = "The Alliance must be purged from this land, {name}!\n\nNo half-measures will do!", sourceObjectiveStatus = "unverified-source-field" }
quests[29967] = { id = 29967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boom Goes the Doonamite!", description = "It's an emergency!\n\nLooks like you stirred up a hornet's nest killin' all them fish-folk.\n\nThey're conductin' a full-on counterattack on Grookin Hill!\n\nI was hopin' to get some R&D time, but we're gunna hafta put my methane-grenade theory to work right away!\n\nMeet me on the east side of the fort, and bring yer throwin' arm!", sourceObjective = "Speak to Rivett east of Grookin Hill. Use his Methane Grenades to fend off the Jinyu attack.", progress = "I think these methane-grenades are gunna impact the environment, if ya know what I mean...", completion = "I'd say repelling the attack is an understatement!", sourceObjectiveStatus = "unverified-source-field" }
quests[29968] = { id = 29968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green-ish Energy", description = "One word: Methane!\n\nWe're going green. Clean burning, high availability, all natural, and will keep the druids off my back when we get back to our neck of the world.\n\nThat, and I ran out of blasting powder...\n\nSo, I need your help, {name}.\n\nNo, no, I wouldn't ask you to do the dirty work - especially not in front of the general. I'll collect these 'deposits' myself.\n\nYou gather up some wood for an outhouse - I'm thinking long-term here!", sourceObjective = "Gather 7 Green Branches in the Dookin' Grounds", progress = "Gotta watch out for the wet ones...whewee!", completion = "Ah, the smell of progress, and methane.", sourceObjectiveStatus = "unverified-source-field" }
quests[29971] = { id = 29971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scouts Return", description = "Hey, while you were out our scouts came back. And get this, they found some Alliance kid.\n\nYou should probably go debrief them.", sourceObjective = "Speak with Shokia in Grookin Hill.", completion = "We may have a problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[29981] = { id = 29981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stemming the Swarm", description = "I'm not from here. I've never even BEEN here before today. But even I can tell you that something's wrong.\n\nThat wall over there was built to keep mantid off of pandaren lands.  Now, the mantid are sending their winged scouts over the top, as if the wall wasn't even there!\n\nThe only reason those spindly scouts aren't dying is because they're attacking farmers, not soldiers. They wouldn't stand a chance against someone like you.", sourceObjective = "Slay 14 Ik'thik mantid in Stoneplow.", progress = "If the flying mantid troops have always been able to fly over, why haven't they before now?", completion = "Lin asked you to help us out? Rather presumptive of her.\n\nStill, we are short-manned. We won't turn down your help... or the girl's. You have our thanks, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29982] = { id = 29982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evacuation Orders", description = "A few farmers remain in the fields... some perilously close to the crumbling wall. I don't want any farmers pretending to be heroes. We will take care of this mantid swarm, and then they can return to their homes.\n\nMy Shado-Pan are too busy defending this town to organize evacuations. You want to prove yourself useful? Get those farmers out of harm's way.", sourceObjective = "Evacuate the Blacksoil Family, the Spadepaw Family, the Greentill Family, and the Marlfur Family.", completion = "A few stubborn ranchers want to make my job harder?\n\n<The Watch Commander sighs.>\n\nFine. I will rob no pandaren of his right to defend his land.", sourceObjectiveStatus = "unverified-source-field" }
quests[29983] = { id = 29983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Master", description = "We should be able to handle the defense of Stoneplow from here on out.\n\n<The Watch Commander motions towards Lin Tenderpaw.>\n\nLin here is searching for someone she calls \"The Hidden Master\". I believe I know who she's talking about, and I have a clue for you.\n\nGo north.", sourceObjective = "Find Master Bruised Paw in the Valley of the Four Winds.", completion = "You seek training?\n\n<The pandaren studies your physique for several seconds, without speaking.>\n\nAlright.", sourceObjectiveStatus = "unverified-source-field" }
quests[29984] = { id = 29984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Fists: Trial of Bamboo", description = "We will start with a test: The Trial of Bamboo.\n\nYour friend Lin failed this test.\n\nFollow me, and listen carefully to my instructions.", sourceObjective = "Speak with Master Bruised Paw, then successfully strike the Stack of Bamboo Reeds 3 times.", progress = "If you cannot pass this test, then there is probably no reason to continue our training.", completion = "You show promise, {name}. We will continue.\n\nIt is now time for your first round of training.", sourceObjectiveStatus = "unverified-source-field" }
quests[29985] = { id = 29985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Will Be Mist", description = "The mist in this forest is a constant nuisance - one which I'm glad to hand off to trainees like you. Strange creatures lurk in the mist between these trees, and they must constantly be pushed back.\n\nConsider this part of your training.", sourceObjective = "Slay 12 Mist Incarnations.", completion = "You follow directions well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29986] = { id = 29986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fog Wards", description = "Trainee.\n\nSeveral wards surround us, hidden in the woods near my home. They are quite effective at dispersing the mist, but they require constant upkeep.\n\nYou will find one to the north, one to the west, and one to the south. Find these wards and light them.", sourceObjective = "Light the Northern Fog Ward, the Western Fog Ward, and the Southern Fog Ward.", progress = "See if you can light one of the wards while one of the mist incarnations is nearby.", completion = "You honor your people, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29987] = { id = 29987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Fists: Trial of Wood", description = "You have progressed in your training, I think. Come with me, and we will attempt the Trial of Wood.", sourceObjective = "Speak with Master Bruised Paw, then successfully strike the Stack of Wooden Blocks 4 times.", progress = "I'm prepared, {name}. Are you?", completion = "You have the gift of focus, {name}. Not many of my students make it this far.", sourceObjectiveStatus = "unverified-source-field" }
quests[29988] = { id = 29988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste For Eggs", description = "I can sense your anxiety, but you are not ready yet. Your training must continue before you perform the final test. As for your task... I need you to fetch me some eggs.\n\nYes, eggs. The marshland atop the hills to the east is home to a number of birds, all of which are generally peaceful in nature. You should have no trouble gathering enough eggs to last me several weeks.", sourceObjective = "Obtain 10 Emperor Tern Eggs, 4 Whitefisher Crane Eggs, and 1 Hornbill Strider Egg.", progress = "How is your egg hunt going?", completion = "Now you know why I don't gather the eggs myself.\n\nShall we continue your training?", sourceObjectiveStatus = "unverified-source-field" }
quests[29989] = { id = 29989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Fists: Trial of Stone", description = "You have accomplished much in the short time you have been here, {name}. I would not normally offer this test so soon... but I feel that you're ready.\n\nIt is time you attempted the Trial of Stone.", sourceObjective = "Speak with Master Bruised Paw, then successfully strike the Stack of Stone Blocks 5 times.", progress = "This test will be trying. You will test the strength of your fists against the strength of stone. Steel yourself, {name}.\n\nNot literally, of course.\n\nUnless you normally wear steel gloves... in which case, you may literally steel yourself.", completion = "<Master Bruised Paw bows before you.>\n\nStone quivers and breaks beneath your fists. You have the power to move mountains, if you so desire.\n\nThere is nothing more I can teach you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29990] = { id = 29990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training and Discipline", description = "I told myself that, if I ever made it here to the Hidden Master, I would learn everything I could from him. This is my chance, {name}. I'm not going to let it slip away.\n\nStill, I fear that Stoneplow needs us. I left early, before we were able to push the mantid scouts back. I'd feel better if you would check in with the Watch Commander for me.\n\nOh, and if you run into the others, maybe you should tell them where the Hidden Master is...", sourceObjective = "Report to Loon Mai at Stoneplow in the Valley of the Four Winds.", completion = "I'm glad to hear that Lin is well.\n\nOur defenses are holding, for now. The mantid continue to send their scouts over the wall, but they haven't gotten much farther than that.", sourceObjectiveStatus = "unverified-source-field" }
quests[29992] = { id = 29992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenderpaw By Name, Tender Paw By Reputation", description = "I'd like to go tell Xiao, Kang, and the others that I've found the hidden master, but now he won't let me leave! He says I have to pass that test of bamboo first.\n\n<Lin whispers:> How'd you do that, by the way?\n\nIt looks like, for the time being, I'm stuck here practicing my punches against this rock. And my knuckles are about to cave in.\n\nIf you could gather some jademoon leaves, I could prepare an ointment and at least numb some of this pain.", sourceObjective = "Gather 18 Jademoon Leaves.", progress = "Ow! Ow! Ow!", completion = "<Lin pauses for a moment to rub the leaves on her swollen paws.>\n\nThank you! I can prepare a proper ointment later, but this will do for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[29993] = { id = 29993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Boy", description = "Have you seen my son, Lo? He was here a moment ago and I told him we were leaving today.\n\nI'm sure he's off trying to woo that young Syra Goldendraft. That is the very reason we need to leave!\n\nNo son of mine is going to run off with a Goldendraft!\n\nI'm going to search around here for them.\n\nI do keep catching those two sneaking off to the Arboretum. Any chance you could head out there and look for them?", sourceObjective = "Speak with Inkmaster Wei.", completion = "You seek two lovers blind to the ambitions of their family names. They were here, seeking a way to hold to their path.\n\nSadly they did not find their answers among the trees or art.", sourceObjectiveStatus = "unverified-source-field" }
quests[29995] = { id = 29995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Dawn", description = "The \"children\" you seek are not actually children but grown pandaren, despite what their elders might claim. Their love will not be held in check by the feuds of their families.\n\nYou will find both Syra and Lo at the Shrine of the Dawn, ever seeking an answer to their dilemma amongst the pandriarchs of old.", sourceObjective = "Search the Shrine of the Dawn for Syra Goldendraft.", completion = "Oh stranger! Please tell me you can help us. They really hurt my Lo.", sourceObjectiveStatus = "unverified-source-field" }
quests[29997] = { id = 29997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scryer's Dilemma", description = "Since you were so helpful at the mines, would you be willing to help us with a small problem here at the temple?\n\nWise Mari has been complaining recently of a disturbance in his temple.\n\nThe water sprites have gotten quite playful recently, and made off with his ceremonial staff.\n\nIf you could help him, I would be most grateful. I may even put in a word with the Jade Serpent for you.\n\nJust follow the path to the north.", sourceObjective = "Kill Water Fiends to recover Wise Mari's Staff.", progress = "The pools are clouded. I will need my staff to calm the spirits and speak to the water.", completion = "I am but an old jinyu, and those pesky water sprites were impossible to catch. Thank you, {name}, for returning my staff to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[29998] = { id = 29998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Librarian's Quandary", description = "Lorewalker Stonestep is in charge of the entire temple library. Lately, something has been troubling him and his work.\n\nWith thousands of ancient tomes to be transcribed, I can't afford to have him distracted.\n\nWould you follow the path south to the library and see what ails him?", sourceObjective = "Speak to Lorewalker Stonestep in the temple library.", completion = "The Elder Sage Rain-Zhu sent you?\n\nVery well. You shall help me.", sourceObjectiveStatus = "unverified-source-field" }
quests[29999] = { id = 29999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider's Bind", description = "Have you seen the young serpents in the training yard?\n\nThe littles ones tend to be mischievous, and some of them ran off to play before the training session.\n\nThe Mistress will get angry if she discovers they're missing.\n\nWould you go find them and bring them back to me? I don't want them to get into trouble.\n\nThey like to play out in the open, so look for them in courtyards and around the spires.", sourceObjective = "Find 4 Playful Serpents.", progress = "I hope they didn't give you too much trouble.", completion = "You found them and brought them all back!\n\nThey've really taken a liking to you.\n\nThank you so much!", sourceObjectiveStatus = "unverified-source-field" }
quests[30000] = { id = 30000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jade Serpent", description = "You came to deliver a message to the Jade Serpent, right?\n\n<The little girl tilts her head up at you inquisitively.>\n\nI guess it's time you met her.", sourceObjective = "Listen to the Jade Serpent.", completion = "Did you deliver your message?", sourceObjectiveStatus = "unverified-source-field" }
quests[30001] = { id = 30001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moth-Ridden", description = "Moths have infested the library. Moths!\n\nAny librarian worth his letters knows that moths are the most dangerous threat to paper, second only to bookworms.\n\nAs it turns out, my assistants are a useless bunch of insect-fearing cowards.\n\nPlease, you MUST help me get rid of the moths immediately! The works of a thousand pandaren storytellers depend on you!", sourceObjective = "Kill 8 Dappled Moths.", progress = "I can see the moths eating the pages from here!", completion = "Yes, yes, thank you! You've thinned out their numbers wonderfully.", sourceObjectiveStatus = "unverified-source-field" }
quests[30002] = { id = 30002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pages of History", description = "The worst possible thing has happened, {race}.\n\nWe. Have. Bookworms.\n\nThis is a critical situation. All Bookworms in the library must be eradicated at once to prevent their spread.\n\nWe must squash this problem, literally! Please examine the infested books in the library and squash any Bookworms that you find.", sourceObjective = "Search through the library books for infestations, then squash 12 Bookworms.", completion = "Oh, wonderful! I am so relieved that we managed to avert disaster.\n\nNo no, don't get too close, please. You still have some squashed bug bits on your shoes.", sourceObjectiveStatus = "unverified-source-field" }
quests[30003] = { id = 30003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Book By Its Cover" }
quests[30004] = { id = 30004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything In Its Place", description = "You have helped us more than you can ever imagine, {name}.\n\nI do not know what I would do if our precious scrolls were ever to be lost.\n\nPlease return to the Elder Sage Rain-Zhu and tell him that the library is in order.", sourceObjective = "Speak to Elder Sage Rain-Zhu at the Temple of the Jade Serpent in Jade Forest.", completion = "Lorewalker Stonestep is back to work?\n\nRemarkable. You were able to do what the last four priests I sent could not.\n\nI...I think my headache is disappearing.", sourceObjectiveStatus = "unverified-source-field" }
quests[30005] = { id = 30005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lighting Up the Sky", description = "Do you like fireworks, <sir/miss>?\n\nI love them! In older times we would set them off to frighten away demons, but I just like them because they're pretty!\n\nI think there are still some old launchers lying around the temple.\n\nWould you go set off some big fireworks for me? It would make me so happy!", sourceObjective = "Set off 8 fireworks.", completion = "Yay! I saw the fireworks all the way from over here!\n\nThank you so much, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30006] = { id = 30006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkness Around Us", description = "Despite our best efforts, the sha broke the seals around the main temple.\n\nIf we cannot hold them back here, their darkness will spread to the rest of the Jade Forest.\n\nWe need your help immediately. Kill any sha creatures that you see. They should not be difficult to find.", sourceObjective = "Kill 15 sha invaders.", progress = "We are holding ground, but just barely.", completion = "Thank you, {name}. Every sha slain is another turn in the tide.", sourceObjectiveStatus = "unverified-source-field" }
quests[30011] = { id = 30011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Vision", description = "Please tell the Elder Sage Rain-Zhu that I will begin my work at once.", sourceObjective = "Speak to Elder Sage Rain-Zhu near the courtyard in the Temple of the Jade Serpent in the Jade Forest.", completion = "Wonderful! Knowing that the scryer has returned to his meditations has lifted a great burden from my shoulders.", sourceObjectiveStatus = "unverified-source-field" }
quests[30015] = { id = 30015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dawn's Blossom", description = "Blood and Thunder! My axe hungers!\n\nWe won't return to Orgrimmar until every last Alliance is purged from this land.\n\nI will train these natives myself, if I have to. One way or another, this land will be made ready for Horde settlement.\n\nIn the meantime, their chief gave me this to pass on to you - a map and a message in some fancy script.\n\nDo what you must, but be quick about it.\n\nWar is brewing...", sourceObjective = "Speak with Lorewalker Cho in Dawn's Blossom.\n\nSpeak to the flightmaster in Grookin Hill for passage.\n\nProvided item:", completion = "Greetings, {name}!\n\nWelcome to Dawn's Blossom, a home of my people.\n\nSadly I must depart. Alas, a Lorewalker's work is never done.\n\nMake yourself at home. Our people could surely make use of one with your talents.", sourceObjectiveStatus = "unverified-source-field" }
quests[30027] = { id = 30027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need a weapon suited to your talents. Retrieve a staff from one of the weapon racks below, bring it to me, and show me that you know how to equip it properly.", sourceObjective = "Retrieve and equip a Trainee's Staff.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use.", sourceObjectiveStatus = "unverified-source-field" }
quests[30028] = { id = 30028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grain Recovery", description = "Since you are heading south, can you try to recover some of the grain that these thieves made off with?\n\nWe saw birds and sprites running off with entire bags of our best bulk stock into the fields east and south of here.", sourceObjective = "Bring 8 Sacks of Grain to Grainlord Kai.", progress = "Between birds and sprites we are never going to meet our quota to the Stormstout Brewery.", completion = "Why thank you very much stranger. This has not been a good day, but you certainly have helped us make it better.\n\nPlease, take this, you've earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[30029] = { id = 30029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wee Little Shenanigans", description = "So... we bought some cheap grains in bulk. It turned out the grain was infested with sprites.\n\nI HATE sprites. With their wee beady eyes and constant smiling.\n\nI would like to resolve this quietly. Can I buy your services to discretely eliminate some of these grain thieves?", sourceObjective = "Kill 8 Tricky Maizers.", progress = "Oh good, they didn't turn you into a frog yet. I saw them do that once you know.", completion = "Thank you for your help stranger! Hopefully we can deal with the rest on our own from here.", sourceObjectiveStatus = "unverified-source-field" }
quests[30030] = { id = 30030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Sprite", description = "Just to be clear, what happened was an accident. What I did, I did for INDUSTRY!\n\nThere was no way I could have known that a sprite invasion would happen at any time, or that one of them would try to eat my new \"Pan's Miracle Gro\" formula.\n\nNow not only do they have a big sprite leading them, but he's one angry beast.\n\nIf I pay you, will you take him out?", sourceObjective = "Defeat Cornan the Barley Barbarian.", progress = "Oh why? Why did I have to tamper with the natural order of things? All I wanted was to make these grains grow faster and more numerous.", completion = "Now that that's over I have some ideas on how to make a new concoction. We'll see.\n\nThank you for your help. Here is your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[30031] = { id = 30031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taste Test", description = "As long as you're here, you might as well help me out. I'm feeling pretty darn unqualified for the task, seeing as I've never drank a drop of beer in my life.\n\nYou should try a little sample of each of their grains. Let's see if any of this stuff is sweet enough for Uncle Chen.", sourceObjective = "Taste the Aged Grain, Light Grain, Fresh Grain, and Malted Grain.", progress = "None of this seems to taste sweet enough! What's the deal?", completion = "Huh. I guess none of that grain is going to work. Uncle Chen is pretty picky.\n\nMaybe the Grainlord knows where we can find something more... special.", sourceObjectiveStatus = "unverified-source-field" }
quests[30032] = { id = 30032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quest for Better Barley", description = "Looking for sweet grain? My father once mentioned a malted cave barley that sounds about right.\n\nIf you are willing to brave the peril, there is an ancient cave at the base of the Winds' Edge south of here.\n\nThere is even an old lift my father made when he would travel into the jungle.\n\nIn the cave is a bush as old as my family. From that bush you can pluck a grain so sweet it will humble your senses.\n\nJust watch out for its guardians.", sourceObjective = "Find the Malted Cave Barley at the base of the Winds' Edge.", progress = "That jungle sounds spooky.", completion = "Now THIS smells like the right stuff!", sourceObjectiveStatus = "unverified-source-field" }
quests[30033] = { id = 30033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a spellblade and a hand fan from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", sourceObjective = "Retrieve and equip a Trainee's Spellblade and a Trainee's Hand Fan.", sourceObjectiveStatus = "unverified-source-field" }
quests[30034] = { id = 30034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need a weapon suited to your talents. Retrieve a crossbow from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", sourceObjective = "Retrieve and equip a Trainee's Crossbow.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use.", sourceObjectiveStatus = "unverified-source-field" }
quests[30035] = { id = 30035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a mace and a book of prayers from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", sourceObjective = "Retrieve and equip a Trainee's Mace and a Trainee's Book of Prayers.", sourceObjectiveStatus = "unverified-source-field" }
quests[30036] = { id = 30036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a pair of daggers from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", sourceObjective = "Retrieve and equip a pair of Trainee's Daggers.", sourceObjectiveStatus = "unverified-source-field" }
quests[30037] = { id = 30037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve an axe and a shield from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", sourceObjective = "Retrieve and equip a Trainee's Axe and a Trainee's Shield.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use.", sourceObjectiveStatus = "unverified-source-field" }
quests[30038] = { id = 30038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need a weapon suited to your talents. Retrieve a sword from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", sourceObjective = "Retrieve and equip a Trainee's Sword.", sourceObjectiveStatus = "unverified-source-field" }
quests[30039] = { id = 30039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Freshly arrived for your training, your first task is simple: Speak to Master Shang Xi.", sourceObjective = "Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the strength and cunning to be a {class}? Or are you destined to a life working in the fields?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil.", sourceObjectiveStatus = "unverified-source-field" }
quests[30040] = { id = 30040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", sourceObjective = "Speak to Master Shang Xi.", sourceObjectiveStatus = "unverified-source-field" }
quests[30041] = { id = 30041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", sourceObjective = "Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the compassion and the keen eye of a {class}? Or are you destined to a life tending to the livestock?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil.", sourceObjectiveStatus = "unverified-source-field" }
quests[30042] = { id = 30042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", sourceObjective = "Speak to Master Shang Xi.", sourceObjectiveStatus = "unverified-source-field" }
quests[30043] = { id = 30043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", sourceObjective = "Speak to Master Shang Xi.", sourceObjectiveStatus = "unverified-source-field" }
quests[30044] = { id = 30044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", sourceObjective = "Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the strength of will to be a {class}? Or are you destined to a life of tending to the shrines?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil.", sourceObjectiveStatus = "unverified-source-field" }
quests[30045] = { id = 30045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", sourceObjective = "Speak to Master Shang Xi.", sourceObjectiveStatus = "unverified-source-field" }
quests[30046] = { id = 30046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chen's Resolution", description = "You know what? I don't have to take this.\n\nI'll show that Uncle Gao what it means to be a real brewer. I'll brew the best beer he's ever tasted, with ingredients I've never even used before.\n\nI'm Chen Stormstout, and I'm the best brewer alive.", sourceObjective = "Meet up with Chen Stormstout at Halfhill.", completion = "Let's make some beer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30047] = { id = 30047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chen Taste Test", description = "Uncle Chen is going to love this. Or... he might tell us to find something sweeter. He's kind of dumb like that.\n\nLet's get this grain back to him at Halfhill.", sourceObjective = "Return to Chen Stormstout.", completion = "Ah! Now these are some beautifully malted grains. The two of you have a good eye and nose.", sourceObjectiveStatus = "unverified-source-field" }
quests[30048] = { id = 30048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Li Li and the Grain", description = "I'll let you in on my brewing plan, {name}: I'm planning on making an Emperor Stout. Done right, it should be dark, roasty, and high in alcohol.\n\n<A frown appears on Chen's face.>\n\nI just realized... I never told my plans to Li Li. She'll have no idea what type of grain to bring back!\n\nCould you speak with her? I need her to bring back the sweetest malted grains she can find.", sourceObjective = "Speak with Li Li at the Imperial Granary in the Valley of the Four Winds.", completion = "{name}? What are you doing here?\n\nSo, Uncle Chen wants sweet malts? No problem! Let's get to the taste testing.", sourceObjectiveStatus = "unverified-source-field" }
quests[30049] = { id = 30049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doesn't Hold Water", description = "Would you mind checking in on Mudmug? He may need some assistance bringing that water back.\n\nI'm sure he'll appreciate the help of a big, strong {class} like yourself to help him shoulder the load.", sourceObjective = "Speak with Mudmug at the Gilded Fan in the Valley of the Four Winds.", completion = "{name}! You here to help out? That's mighty swell of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30050] = { id = 30050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gardener Fran and the Watering Can", description = "You want me to just GIVE you some hops? Pfshh! This is the third time today some little {race} like you has come up to me asking for food!\n\nYou want food? Then you'd better work!\n\n<She shoves a watering can into your hand.>\n\nNow go water my plants!", sourceObjective = "Listen to Gardener Fran's orders and water 60 of her vegetables.\n\nYou can water plants while mounted.", progress = "Water my plants you lazy {class}!", completion = "Hmmph!\n\nNice farming.", sourceObjectiveStatus = "unverified-source-field" }
quests[30051] = { id = 30051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Water Hunt", description = "Look at it, {name}: the Gilded Fan. I heared lots of good things about the water they got here. Lots of bad things, too.\n\nNo sayin' what kind of water Chen's gonna be needin', so what say we make him a little sampler platter?\n\nCome on, let's get movin'. We'll go scoop up some water together.", sourceObjective = "Guide Mudmug to Swirling Pools within the Gilded Fan, and help him collect 30 pawfuls of Gladewater.\n\nIf you become separated from Mudmug, you can find him next to the giant banana in the Gilded Fan.", progress = "That Stormstout feller says that he's the best brewer that ever was. Might be true, couldn't tell ya one way or the 'nother as of yet.", completion = "Lookee that, neighbor! That is quite the collection of water we got here. With magical water like this, I'm sure that Chen'll make a brew that really shines.\n\nOr possibly a brew that lands someone in the outhouse for a month. I guess we'll just have to wait and see.", sourceObjectiveStatus = "unverified-source-field" }
quests[30052] = { id = 30052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weed War", description = "You want some hops? I've got plenty in the shed out back. I'll gladly share some with you... if you'll help me weed my field.\n\nNow \"hop\" to it! Get it?", sourceObjective = "Pull 100 weeds from Gai Lan's field.\n\nYou can pull weeds while mounted.", completion = "You weed like a champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[30053] = { id = 30053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hop Hunting", description = "With Li Li fetching grain, and Mudmug handling our water, all we need is hops, and some good wood barrels. I'll handle the barrels... but I need you to gather the hops.\n\nI don't know much about the hops from this land, but I'm sure the nearby farmers have something worth brewing with. Go see what you can rustle up.", sourceObjective = "Ask Gardener Fran, Gai Lan, and Den Mudclaw for hops.", sourceObjectiveStatus = "unverified-source-field" }
quests[30054] = { id = 30054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enough is Ookin' Enough", description = "Virmen, they bite too much.\n\nThey bite Mung-Mung's carrot. They bite Mung-Mung's pumpkin. Mung-Mung try to shoo them away, and the dookers bite Mung-Mung's tail and foot.\n\nEnough is ookin' enough.\n\nYou fight way better than Mung-Mung does. Bring back their bitey teeth. Then we see who does the biting.", sourceObjective = "Obtain 100 Virmen Teeth.", progress = "You bring back those teeth, and maybe Mung-Mung will have some hops for you.", completion = "So many teeth! Maybe Mung-Mung will glue them together to make a tiny rake.", sourceObjectiveStatus = "unverified-source-field" }
quests[30055] = { id = 30055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormstout's Hops", description = "All three farmers have delivered their hops to Halfhill. Perhaps you should check in with Chen to make sure that he received them.", sourceObjective = "Return to Chen Stormstout in Halfhill.", completion = "Look at all these hops! This is quality stuff, too.\n\nWe're making headway, {name}. Soon we'll have all the ingredients to finally start brewing.", sourceObjectiveStatus = "unverified-source-field" }
quests[30056] = { id = 30056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Farmer's Daughter", description = "Brave {class}, you could not have arrived at a better time. My daughter is missing!\n\nI've got a suspicion that the virmen took her down into that stinking little warren of theirs. I'm too old to fight virmen, and my farmhand is already exhausted from fighting them off all morning.\n\nCould you look for her?", sourceObjective = "Find Mina Mudclaw.", completion = "No... no... get back... I don't want...\n\nWait, you're not a carrot. You're not a virmen either. You're here to save me?", sourceObjectiveStatus = "unverified-source-field" }
quests[30057] = { id = 30057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing Orange", description = "Those virmen... they make me do horrible, horrible, silly things. All involving carrots. I couldn't tell you how many carrots they threw at me.\n\nLet's not waste any more time. Get me out of here!", sourceObjective = "Bring Mina Mudclaw back home to her father.", completion = "What's all this fuss about carrots? I don't get it.", sourceObjectiveStatus = "unverified-source-field" }
quests[30058] = { id = 30058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mothallus!", description = "The esteemed Journeyman Chu would appear to have created a monster. It is silken death with wings.\n\nMothallus.\n\nYou have already faced its brood. Now we ask that you help us face the creature itself.\n\nPlease, {class}, venture into the pit and rifle the bait. This will bring the beast to you.\n\nOur mothfighters will assist you as you need, though silk tends to stick to them more than most so you may need to help them, should they become overwhelmed.", sourceObjective = "Bait and defeat Mothallus.", progress = "Have you vanquished the beast?", completion = "We are pursuing perfection in our art and in ourselves. Along the way many mistakes will be made.\n\nI'm sure by tomorrow this field will be swimming with more mistakes. Still, we thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[30059] = { id = 30059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Moth Rebellion", description = "Oh... oh good! A {class}! Could you help me?\n\nI created a strain of vile monsters during my experiments to improve silk output.\n\nThe result was a full-scale moth rebellion. Can you use your {class}iness and destroy some of these mutants?", sourceObjective = "Kill 6 Mutated Silkmoths and 8 Tiny Mutated Silkmoths.", progress = "Master Goh keeps telling me I need to relax and that failure is part of learning. But this is a dangerous failure.\n\nThe kind that might get people killed.", completion = "It seems like there's not QUITE as many corrupted moths out there. At the very least, you've bought me some more time before I get in big, big trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[30063] = { id = 30063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind the Masks", description = "The sha may seem unstoppable, but this is not true.\n\nTheir masks seem to be the source of their power. When a sha and its mask are separated, the creature's essence is banished back to its own realm.\n\nBring me intact masks, for I wish to study them further. Do be careful. I'm sure the sha will not part with them easily.", sourceObjective = "Collect 8 Masks of Doubt.", progress = "Please handle the masks carefully. If you are not careful, they will attempt to consume you.", completion = "I suspect these masks allow the sha to make a physical connection to our world.\n\nI must study them further if we are to banish these creatures forever.\n\nThank you, {name}. Your aid is greatly appreciated.", sourceObjectiveStatus = "unverified-source-field" }
quests[30064] = { id = 30064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Sutras", description = "My adepts had to abandon their studies when the sha invasion began.\n\nUnfortunately, they left their books scattered around the temple grounds. These priceless works of knowledge must be saved!\n\nThe sutras can be found near the Training Pit and the Adept's Ring to the northeast.", sourceObjective = "Collect 6 Ancient Sutras.", progress = "How are the sutras? Are they damaged?", completion = "Thank you! What a relief it is to see these texts are safe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30065] = { id = 30065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arrows of Fortune", description = "Our war supplies grow low, but especially needed are additional arrows.\n\nOur serpent riders are skilled marksmen, but they can do little without ammunition.\n\nWe need someone to brave the battlefields and retrieve any undamaged arrows to refill our stores.\n\nEvery arrow you retrieve will be used wisely.", sourceObjective = "Collect 8 Defender's Arrows.", progress = "Were you able to find any arrows?", completion = "These arrows are still in good shape. They will fly straight and true.\n\nGreat work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30066] = { id = 30066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Power", description = "Our temple defenders have battled relentlessly for hours. No doubt they grow tired.\n\nI will give you mantras to deliver to our fighters.\n\nDo not be fooled by these pieces of paper. These ancient scriptures hold words of untold power.", sourceObjective = "Deliver Ancient Mantras to 6 Yu'lon Guardians or Yu'lon Adepts.", progress = "Words hold great power. Use them wisely.", completion = "The sha's numbers are unending, and our numbers few. But we are not daunted by difficult odds.\n\nThank you for doing your part to protect our home, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30067] = { id = 30067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow of Doubt", description = "A terrible manifestation of the sha has appeared to the south.\n\nIt is trying to destroy an ancient relic, the Bell of a Thousand Whispers.\n\nThis bell has never been rung in the temple's history, for it is rumored to be an ancient instrument of power.\n\nPlease go and defeat this demon where it stands! We must save this relic!", sourceObjective = "Defeat the Shadow of Doubt.", progress = "The bell is said to contain the voices of a thousand fallen temple priests.", completion = "You have saved us. From what fate, I dare not imagine.", sourceObjectiveStatus = "unverified-source-field" }
quests[30068] = { id = 30068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flames of the Void", description = "Do you see the violent black and white flames erupting all around the temple?\n\nThe greater our doubt, the stronger they rage. Unchecked, they will devour the entire temple.\n\nWe have but one hope.\n\nTake flight on one of our war serpents. Fly it near the pure springs of water, and then douse the fires with water from the pools.", sourceObjective = "Fly your War Serpent near Pure Water Springs, then douse 6 Void Flames with the water carried in its mouth.", progress = "These fires burn unlike anything in our world.", completion = "You have done much to help curb the fires. Thank you for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[30069] = { id = 30069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Plan Survives Contact with the Enemy", description = "Quickly and quietly; that's how SI:7 prefers to operate. That was the plan, at least.\n\nRell Nightwind is already inside Garrosh'ar Point looking for signs of Anduin and Taylor, but it's getting hot in there and he needs support.\n\nFight yer way through these dogs and find Rell!", sourceObjective = "Kill 6 Garrosh'ar Grunts and 6 Garrosh'ar Gear-Greasers.", progress = "This place is crawling with Horde soldiers - we can't advance on their leader with so many at our backs.", completion = "Great work! If you ever decide to give up your life of adventure, the SI:7 could use more talent like you...", sourceObjectiveStatus = "unverified-source-field" }
quests[30070] = { id = 30070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Ga'trul", description = "Alright <lad/lass>. We've taken enough jabs at this warlock army... now it's time to cut off the head.\n\nGa'trul's back there, in that big ol' temple ruin. Give him a good what-for, and the Horde will have lost its last stake here in Pandaria.", sourceObjective = "Slay Ga'trul.", completion = "Sha...\n\nFighting the Horde on a foreign shore is hard enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[30072] = { id = 30072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Silk Comes From", description = "Would you like to be a Silkmaster for a day?\n\nThe first thing you'll need are fresh mulberry leaves. You can find them in our grove of mulberry bushes to the northwest.\n\nNext you will need to feed them to a hungry silkworm in our feeding pit to the west.\n\nAnd finally you should get some raw silk from our processing hut on the south side of our farm.\n\nHave fun!", sourceObjective = "Obtain Mulberry Leaves, feed 5 Hungry Silkworms, and get Raw Silk.", progress = "Have you found all of the items? Did you pay close attention to our process?", completion = "Superb specimens. I will see to it they find their way to the right place. Please enjoy this free sample.", sourceObjectiveStatus = "unverified-source-field" }
quests[30073] = { id = 30073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emperor", description = "We have everything we need. It's time to start brewing.\n\nPay attention, {name}... you might learn a thing or two.", sourceObjective = "Stand by and help Chen Stormstout with his brew.", progress = "It takes more than three seconds to make beer, {name}. Even when your name is Chen Stormstout.", completion = "Thanks for waiting so long. You are as patient as you are brave.", sourceObjectiveStatus = "unverified-source-field" }
quests[30074] = { id = 30074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knocking on the Door", description = "Now, onward to the Stormstout Brewery! It's high time that I was reunited with the rest of the Stormstouts... and what better way to reunite than over a few mugs of ale?\n\nYou know where the brewery is, right? Just follow this road to the west. You can't miss it. Of course, you're free to share the road with us - we'll be leaving any moment now.", sourceObjective = "Meet up with Chen Stormstout at the entrance of the Stormstout Brewery.", completion = "The door... it's boarded up?", sourceObjectiveStatus = "unverified-source-field" }
quests[30075] = { id = 30075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Way", description = "Are you seeing this? Virmen, hozen, and water sprites... all pouring out of the brewery doors and windows! What the heck is going on in there!?\n\nThere is another entrance, on the eastern side of the brewery. I'm going to run over there and try to figure out what's going on. In the meantime, see if you can't get rid of these creatures. There's nothing worse than a drunken hozen.", sourceObjective = "Slay 10 Ale-Addled Hozen or Mischievous Virmen.", progress = "This brewery - it's a disgrace to the Stormstout name! Something needs to be done!", completion = "I've had just about enough of this brewery. I'm starting to think that you and I should just bust down the wall and clean house.", sourceObjectiveStatus = "unverified-source-field" }
quests[30076] = { id = 30076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fanciest Water", description = "I've heard lots of cockamamie rumors about this here brewery. I thought they were all false... until I saw that giant hozen.\n\nSo, it got me thinkin', what if the other rumors are true? I heard this one rumor just the other day about some water sprites that run around inside the brewery, causin' a ruckus and whatnot. Their bodies are actually MADE OF WATER.\n\nI reckon a man could make some mighty fine beer with some fancy water like that. If you find any, could you bring me some?", sourceObjective = "Obtain 3 Spritewater Essences.", progress = "This is gonna be great. It'll be just like makin' beer, but instead of water, I'm gonna use water sprite meat.", completion = "Looks like plain ol' water to me. It's hard to believe it's actually the corpse of a real, honest-to-goodness walkin'-around living thing.\n\nCan't wait to turn it into beer and drink it.", sourceObjectiveStatus = "unverified-source-field" }
quests[30077] = { id = 30077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels, Man", description = "I can't believe that giant hozen! He's just throwing barrels everywhere!\n\nBarrels, man!\n\nIt looks like he managed to get pretty much all the pandaren that were working out in front of the brewery. If I were you, I'd help some of them break out. Put some of those ridiculous muscles to use.\n\nWe're headed over to the brewery's rear entrance, to the east. Meet you there!", sourceObjective = "Free 7 Barreled Pandaren.", progress = "Barrels.", completion = "What is it with monkeys and barrels, anyway?", sourceObjectiveStatus = "unverified-source-field" }
quests[30078] = { id = 30078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning House", description = "That's it, {name}. I've had enough of this.\n\nIf somebody doesn't do SOMETHING to take care of this brewery, we'll lose it forever. And there's far too much family history - and beer - in there to risk wasting.\n\nSo... we're going to break in through the back door. You, Li Li, Mudmug, and me.\n\nIt's gonna be a brawl in there.\n\nLet me know when you're ready.", sourceObjective = "Defeat Eddy, Jooga, and the Fizzy Yellow Alemental.", progress = "Let's do this.", completion = "Take a look around - it's a lot calmer outside. All the brewery needed was somebody strong to take care of it.\n\nIt's going to take some time to clean this place up, but I don't really mind that so much.\n\nThis is, after all... my home.", sourceObjectiveStatus = "unverified-source-field" }
quests[30079] = { id = 30079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Eating Zhu's Watch?", description = "Pandaren always welcome travelers with open arms - and open kegs! But this town full of jerks!\n\nEveryone so busy sulking, they won't talk to Ken-Ken at all!\n\nCan you find someone in town who will talk to us? Maybe normal pandaren just hiding in the houses?", sourceObjective = "Speak with the inhabitants in Zhu's Watch and find someone willing to talk to you.", progress = "Something definitely not right! {race} supposed to be HAPPY!", completion = "Only one lady-panda who's not crazy? This worse than Ken-Ken thought...", sourceObjectiveStatus = "unverified-source-field" }
quests[30080] = { id = 30080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Yi-Mo", description = "My nephew, Yi-Mo, has always been sort of a downer. When this wave of despair hit the town, he took it harder than most. He sat around for days refusing to eat, just staring off into the horizon.\n\nNow he's wandered off toward the cliffs northeast of here, where the thunderbirds nest and hunt.\n\nPlease, {class}, will you look for him?", sourceObjective = "Look for Yi-Mo Longbrow somewhere northeast of Zhu's Watch.", progress = "<Yi-Mo lets out a long sigh.>", completion = "Let me guess: my aunt sent you?", sourceObjectiveStatus = "unverified-source-field" }
quests[30081] = { id = 30081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materia Medica", description = "Alright, Ken-Ken pretty sure he knows what wrong with pandaren! Got old, old hozen remedy that do the trick.\n\nNeed to mix honey, fish oil, and salt. Ken-Ken saw lots of beehives in the trees around town, and there must be fish left in the dry ponds.\n\nThat just leave salt... Mei might know where we can find some.", sourceObjective = "Gather 4 Chunks of Honeycomb, 4 Slick Mudfish, and 4 Salty Cores from Zhu Province.", progress = "Can't believe Ken-Ken did not think of this sooner. It's the ONE thing that can ruin his day...", completion = "Pandaren got a case of the spooky-dooks!\n\nDooks get scared sometimes, don't wanna come out. Poor, fluffy mopey-dopes must be ready to explode by now!\n\nThis just the thing to bring 'em out. That make pandaren happy for sure!\n\nJust like ol' gramma used to say: can't THROW if can't GO!", sourceObjectiveStatus = "unverified-source-field" }
quests[30082] = { id = 30082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cheer Up, Yi-Mo", description = "Ever since this storm began, I've just been... tired.\n\nNot physically... no. It's like my very soul is exhausted. Worthless. Hopeless. I imagine it's what one feels when a mate leaves them for someone with a rounder belly, but I've never had a mate so how would I know?\n\nHow can I claim to know anything? I'm worthless to everyone but these thunderbirds. At least they'll have a good meal out of me.\n\n<Yi-Mo sighs deeply and continues staring off into the sky. It doesn't look like he's going anywhere.>", sourceObjective = "Bring Yi-Mo Longbrow back to Zhu's Watch.", completion = "I can't believe he was actually going to do that... This despair is worse than I had even imagined.\n\nI cannot thank you enough for bringing him back.", sourceObjectiveStatus = "unverified-source-field" }
quests[30083] = { id = 30083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Province", description = "With our grip on the province loosening, saurok from the wilds have already moved in to the cave just north of town.\n\nMost of our hunters are face-down in their own tears, so the saurok just walk in here like they own the place and grab whatever they want!\n\nI want to send a message that Zhu's Watch is not to be crossed.\n\nWill you be my messenger?", sourceObjective = "Kill 10 Wildscale Saurok or Wildscale Herbalists in Zhu Province.", progress = "We cannot let the saurok walk all over us anymore.", completion = "Thank you, {name}. That should teach those savages to know their boundaries.", sourceObjectiveStatus = "unverified-source-field" }
quests[30084] = { id = 30084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borderlands", description = "Bonfires are surprisingly effective at discouraging beasts from wandering out of the wilds. We have three along the border to the southwest which we normally keep lit at all times.\n\nNobody's been there for days, though, and the fires must be out by now. It's only a matter of time before the wilds creep back in and overtake the land we have kept safe for centuries.\n\nPlease, re-ignite the bonfires. They are critical in keeping the province safe, and they are memorials to the founders of our way of life.", sourceObjective = "Light the Memorial Flame of Zhu, Memorial Flame of Rin, and Memorial Flame of Po along the southwest border of Zhu Province.", progress = "Zhu warned against the dangers of trying to conquer the wilds, and asked only that we contain them.\n\nThe bonfires honor his wishes and his spirit.", completion = "Thank you, {name}.\n\nZhu Province serves as a corridor from the upper tier of the valley down to the sea.\n\nKeeping the province safe requires daily efforts to maintain a border against the savage Krasarang Wilds.", sourceObjectiveStatus = "unverified-source-field" }
quests[30085] = { id = 30085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Brewery", description = "We need to find out what's going on inside that brewery, {name}!\n\nWe may have cleared out some of the bigger pests, but I'm certain there's plenty more where they came from. Gather up a few of your friends, and meet me inside!", sourceObjective = "Speak to Chen Stormstout inside the Stormstout Brewery.", completion = "You came! Great!\n\nI'm looking forward to fighting by your side again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30086] = { id = 30086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for the Hidden Master", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs.\n\nI'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I are trying to decide something. We can talk again afterwards.", sourceObjective = "Listen to Xiao and his companions.", completion = "Were you listening in? Don't worry, I don't mind. You're welcome to search for the hidden master as well.\n\nThough, if you do find him, I'd appreciate if you came back here and told me where he was.", sourceObjectiveStatus = "unverified-source-field" }
quests[30088] = { id = 30088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Why So Serious?", description = "Okay, so that not work. Well... it cheer Ken-Ken up! But pandaren still sad...\n\nWe try another old hozen remedy - this time, we go back even further than gramma, way WAY back to ancient times. Hozen still do this sometimes... mostly at parties.\n\nKen-Ken got woodworking to do - you bring him teeth! Not yours; big ones, like a panther would have!\n\nOh, and some paint! Mei might know where to find.", sourceObjective = "Collect 18 Huge Panther Fangs and 1 Jar of Pigment from Zhu Province.", progress = "<Ken-Ken is hard at work carving something out of tree bark.>\n\nThis gonna be great, you'll see.", completion = "Just in time! All done... look!\n\n<Ken-Ken holds up a carved wooden mask with a ridiculous face.>\n\nNow we put on finishing touches and we gots a guaranteed FUN MACHINE!", sourceObjectiveStatus = "unverified-source-field" }
quests[30089] = { id = 30089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apply Directly to the Forehead", description = "Well... THAT was unexpected!\n\nCome to think of it, now Ken-Ken remember why hozen use mask in the first place...\n\nA legend about the Monkey King says he used a mask to cure old pandaren emperor, Shaohao, when he was too sad to lead his people. Then they buried mask--with all his sadness--in the ground.\n\nWe should use the mask on more pandaren, but instead of putting sad away in ground, we gonna PUNCH ITS BUTT.\n\nLet's do this, {name}!", sourceObjective = "Use Ken-Ken's Mask to cure 8 Despondent Wardens of Zhu in Zhu's Watch.", progress = "This must be the emperor's sad coming back! That is some oooold sad.\n\nKen-Ken bet pandaren sad get stronger with age, too, like pandaren booze.", completion = "We saving pandaren, but the land still sad... Look, rain's not stopping at all!\n\n<Ken-Ken shakes his tiny fists at the sky.>\n\nHow many more butts we gotta punch before we fix this town?!\n\n<The sky darkens in response.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30090] = { id = 30090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zhu's Despair", description = "Hmm... Is that Yi-Mo kid over there?\n\n<Ken-Ken squints against the increasing torrents of rain.>\n\nIt is! He's at the well, and he's not lookin' so good.\n\nKen-Ken got a bad feeling about this...", sourceObjective = "Exorcise the Sha of Despair energy from Yi-Mo Longbrow in Zhu's Watch.", completion = "We did some good work here today, {name}.\n\nMonastery always tell us to leave a place better than we find it.", sourceObjectiveStatus = "unverified-source-field" }
quests[30091] = { id = 30091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of Pandaria", description = "All of this started with our ponds. In a single day, all of the water retreated down into the earth. When there was no more water in the ponds, it began to fall from the sky.\n\nDespite endless torrents of rain, the ponds do not fill. It's as if the land itself thirsts and cannot be quenched.\n\nNow the ponds birth horrific manifestations of despair. Elementals made of water from the sky and salt from the earth; the tears of Pandaria.", sourceObjective = "Kill 12 Weeping Horrors in Zhu Province.", progress = "I don't know why this is happening, but I can say for certain that those elementals were the start of it all.", completion = "Thank you, {class}.\n\nIt's time we take back our land from this curse.", sourceObjectiveStatus = "unverified-source-field" }
quests[30092] = { id = 30092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Man in Gilneas", description = "If you wish to join my cause and slaughter the black dragons in hiding, prove yourself by taking down Hiram Creed. He's amassing an army in Gilneas.\n\nWe haven't been able to slip past his defenders, but we've got a man on the scene keeping an eye on him. Zazzo Twinklefingers, a very crafty arcane mage, is waiting for us to contact him just outside of the ruins of the Gilnean capital.\n\nFind him and he'll direct you to the target.", sourceObjective = "Seek out Zazzo Twinklefingers near the ruins of Gilneas City in Gilneas.", completion = "Ravenholdt sent you? I hope you're a better assassin than the others.", sourceObjectiveStatus = "unverified-source-field" }
quests[30093] = { id = 30093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assassinate Creed", description = "The city has been in chaos for days now. Hiram Creed, disguised as a Gilnean, has infected the lot of those dogs with his own draconic blood. Even the Forsaken are having trouble routing him out.\n\nOnly a surgical assassination can end this!\n\nThe bridge behind me is relatively unguarded. Slip in through merchant's square and head south - you'll find Creed in the middle of the military district.\n\nI'll keep an eye on you and pull you out if there's any trouble.\n\n...There WILL be trouble!", sourceObjective = "Stealth into the ruins of Gilneas City and slay Hiram Creed within the military district.", progress = "Hiram Creed. Among the black dragons, he is known as \"Creetharus.\"", completion = "Creed is finished. The Gilneans who followed his lead are on their own now - assuming his corrupted draconic blood works its way out of their system without killing them.\n\nEither way they're no longer a concern of ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[30094] = { id = 30094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End Time", description = "Nozdormu, the bronze Aspect, has asked for help from the champions of the Horde. You are on his short list. I can share few other details.\n\nIt is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself.\n\nHe awaits you at the End Time, in the distant future. I can help you to travel there, if you so choose.", sourceObjective = "Speak with Nozdormu at the End Time.", completion = "{name}, you have arrived. This is good. I apologize for bringing you to this strange place, and under such suspicious circumstances.\n\nI have a good reason for doing so.\n\nWe are going to kill Deathwing. And I require your aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[30095] = { id = 30095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End Time", description = "Nozdormu, the bronze Aspect, has asked for help from the champions of the Alliance. You are on his short list. I can share few other details.\n\nIt is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself.\n\nHe awaits you at the End Time, in the distant future. I can help you to travel there, if you so choose.", sourceObjective = "Speak with Nozdormu at the End Time.", completion = "{name}, you have arrived. This is good. I apologize for bringing you to this strange place, and under such suspicious circumstances.\n\nI have a good reason for doing so.\n\nWe are going to kill Deathwing. And I require your aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[30096] = { id = 30096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murozond", description = "If we are to destroy Deathwing, we will need the power of the Dragon Soul. To obtain the Dragon Soul, I would have to take you back to the Sundering, ten thousand years in the past... but that time passage is blocked to me.\n\nThe creature that blocks us from accessing this time passage is named Murozond. He must be slain, here, in this twisted future, before we can continue our plot to unmake Deathwing.\n\nThis is why you were brought here, {name}.", sourceObjective = "Slay Murozond.", progress = "This is a future of Azeroth, yes... but not an inevitable one.\n\nThis future is what my fellow aspects are trying to avoid.", completion = "Murozond is no more. The timeways are open to me once again.", sourceObjectiveStatus = "unverified-source-field" }
quests[30097] = { id = 30097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archival Purposes", description = "From what I understand, you intend to avoid this future. If this is true, then we must archive data from this timestrand before it is lost to us.\n\nWe believe that the most interesting and valuable elements of this future are the powerful \"echoes\" that roam the dragonshrines.\n\nTake this vessel with you as you silence these echoes. A portion of their energies will be archived within the bronze dragonflight's depository.", sourceObjective = "Slay two of the Echoes within the End Time, then allow Alurmi's Vessel to archive their information.", progress = "Nozdormu is acting with haste. This is something that Nozdormu does not usually do.\n\nNormally I would be more thorough with my archival. However, given the circumstances, we are forced to pick and choose what we record... and to employ the help of mercenaries like you.", completion = "<Alurmi collects the vessel from you.>\n\nI will handle these from here. Of course, they must be properly labeled, documented, and stored.", sourceObjectiveStatus = "unverified-source-field" }
quests[30098] = { id = 30098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Well of Eternity", description = "We must move quickly, before any remaining Infinite agents intervene. Time is precious.\n\nI will now take you from your distant future into your distant past... the War of the Ancients. Our goal is the Dragon Soul, an artifact of immense power... enough power to break Deathwing, and end his reign over your present.", sourceObjective = "Speak with Nozdormu at the Well of Eternity.", completion = "Let us proceed.", sourceObjectiveStatus = "unverified-source-field" }
quests[30099] = { id = 30099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Unending Numbers", description = "Between us and the Dragon Soul lies a legion of demons. They will have to be dispatched before we proceed.\n\nIf my timing is correct - and it usually is - a young night elf named Illidan Stormrage should be crossing our path shortly. He will undoubtedly be of some use when it comes to demon hunting.\n\nHelp Illidan disable the demons' portals, then slay their leader, Peroth'arn.", sourceObjective = "Disable the three demon portals, then slay Peroth'arn.", progress = "You should temporarily lay aside any prejudices you may carry against Illidan. Remember, you are ten thousand years in your past, and he must not be punished for any future crimes.", completion = "Good. We march on.", sourceObjectiveStatus = "unverified-source-field" }
quests[30100] = { id = 30100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vainglorious", description = "Queen Azshara and her royal guard lie ahead of us. We cannot afford the possibility of any interference with our plan. So we will take the fight to her, before she has a chance to meddle.\n\nIt is quite unlikely that you will kill Queen Azshara today; very few coherent timelines exist along that branch. Consider it a victory if you are simply able to occupy her attention, however temporarily.", sourceObjective = "Dispatch of Queen Azshara.", progress = "Azshara and her fawners have long prepared for this day. She will not take our interference lightly.", completion = "We are but moments away from the Dragon Soul.", sourceObjectiveStatus = "unverified-source-field" }
quests[30101] = { id = 30101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to the Dragon Soul", description = "I cannot simply fly up and grab the Dragon Soul. The old gods protect it.\n\nTo make matters worse, their shield is strengthened by the swirling, arcane energies that emanate from the Well of Eternity, and those energies are being focused by the great demon Mannoroth.\n\nDistract Mannoroth, and the link between the Dragon Soul and the Well will be broken. Without the Well's power, the old gods' ward will be weakened, and the Dragon Soul will be vulnerable.\n\nAnd then I will take it.", sourceObjective = "Slay Mannoroth.", progress = "What?", completion = "Thank you for your help, stranger.\n\nYou fight well. I hope to fight with you again in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[30102] = { id = 30102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hour of Twilight", description = "There's no need to stand around here forever. Have you forgotten? We can CONTROL TIME. Especially since you got rid of that Murozond fellow, back in the future.\n\nThat Dragon Soul that you just liberated? Thrall already has it, back in your present day. And he's going to need your help.\n\nYou ready to go?", sourceObjective = "Speak with Thrall at the Hour of Twilight.", completion = "You've arrived.\n\nGood, let us begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[30103] = { id = 30103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Wyrmrest!", description = "The Dragon Soul... a weapon with enough power to defeat Deathwing. Thanks to you, it is now safely in our hands.\n\nCome! The aspects await us. We must bring the Dragon Soul to Wyrmrest Temple, in the center of Dragonblight.", sourceObjective = "Escort Thrall safely to Wyrmrest Temple.", progress = "Come, {name}. We do not have much further to travel.", completion = "I owe my life to you, heroes.\n\nNow that we hold the Dragon Soul safely within Wyrmrest, it may be that all of Azeroth owes their lives to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30104] = { id = 30104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Documenting the Timeways", description = "You... {name}, was it? You assisted with our archival in the past. Well, technically it was the future, but I believe you understand. Time is highly relative.\n\nI require more information for our archive. While you and Nozdormu don't intend to overwrite this timestrand, as you did in the End Time, we can still benefit from more data.\n\nI require information on Captain Varo'then, one of Azshara's pretty little handmaidens, and... hmm... oh, how about that big felguard, just down those stairs?", sourceObjective = "Slay a Legion Demon, a Royal Handmaiden, and Captain Varo'then, then allow Alurmi's Vessel to archive their information.", completion = "We rarely enjoy the opportunity to employ a brave {class} like you. Our archive grows more thorough, thanks to your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[30105] = { id = 30105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Prophet", description = "The missive reads as follows:\n\n\"The Hour of Twilight is upon us. The world-shaman Thrall approaches Wyrmrest with the Dragon Soul in hand, feebly whimpering one final threat to destroy our glorious master.\"\n\n\"Stop Thrall, and we win our war. I will be watching you from nearby.\"\n\n   ~ The Twilight Prophet", sourceObjective = "Find and unmask the Twilight Prophet.", progress = "I have my suspicions about this Twilight Prophet.", completion = "It is truly as we foresaw: Benedictus was the Twilight Prophet. And now he is no more.\n\nWe dealt a mighty bow to the Twilight's Hammer today. Let us hope that it was a deathblow.", sourceObjectiveStatus = "unverified-source-field" }
quests[30106] = { id = 30106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deed is Done", description = "Prince Wrathion will be pleased to hear that you've succeeded. You should report back to him at Ravenholdt Manor.\n\nThe Prince has been known to be extremely generous to those who help him.", sourceObjective = "Report your success to Prince Wrathion at Ravenholdt Manor in Hillsbrad Foothills.", completion = "That's wonderful news, {name}. Creed was not the most powerful of the remaining black dragons, but his manipulation of the Gilneans was truly diabolical.\n\nI've prepared a reward for you. These blades may not look like much at present, but in the right hands they may yet awaken.\n\nPerhaps in YOUR hands...", sourceObjectiveStatus = "unverified-source-field" }
quests[30107] = { id = 30107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cluster Clutch", description = "The daggers I have given you are lifeless shells. They can do great things, once they are given a means to contain the power I have in mind.\n\nI need for you to acquire Shadowy Gems for me. The facets of these unusual stones are like windows into the infinite. They are often used by minions of the Twilight's Hammer to control the most powerful of elementals.\n\nA great battle is raging around Wyrmrest Temple. Collect Elementium Gem Clusters from Deathwing's minions and bring the gems to me.", sourceObjective = "Collect 333 Shadowy Gems by looting Elementium Gem Clusters from creatures in the Dragon Soul Raid encounter.", progress = "How many gems have you collected?\n\nAre my father's minions as twisted as he?", completion = "Ah, do you see how they shimmer? Many fine gems sparkle in the light, but only these seem to sparkle with darkness.\n\nI'll perform an enchantment on these while you are on your next mission.\n\nAre you ready?", sourceObjectiveStatus = "unverified-source-field" }
quests[30108] = { id = 30108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Man in Karazhan", description = "Your next target is the Black Dragon Nalice, who is engaged in some sort of arcane debauchery beneath the ruined tower of Karazhan.\n\nYour primary mission is to destroy her, but if you can bring me back a vial of her blood, I'll be able to use it to augment the power of the daggers I've given you.\n\nYour accomplice Zazzo has already been dispatched to the scene and awaits you there. He'll have more details.", sourceObjective = "Report to Zazzo Twinklefingers in the ruins just southeast of Karazhan.", completion = "Madness. Insanity!\n\nI don't know what Nalice is up to down there, but the entire basement radiates with diabolical arcane energy. She's got an entire cult worshipping her as a goddess.\n\nIf we're going to take her out, we have to do it soon. I hope you're ready for this!", sourceObjectiveStatus = "unverified-source-field" }
quests[30109] = { id = 30109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Betrayer", description = "I've pinpointed Nalice to the Master's Cellar, an extended basement you'll find in the ruins up ahead.\n\nDragon cultists are everywhere, and Nalice has set up some strange arcane storage devices throughout the area. Perhaps you can use those to your advantage?\n\nSneak past the cultists, obliterate Nalice, and grab a vial of her blood for Wrathion.\n\nI'll keep my eyes on you and pull you out if you get into any trouble. But I'm NOT coming in there with you!", sourceObjective = "Sneak into the Master's Cellar in the ruins around Karazhan, defeat Nalice, and acquire a Vial of Black Dragonsblood.", progress = "Nalice. Dead?", completion = "You did it? She's dead? Unbelievable! You're some kind of miracle-worker!\n\nHere, let me see that blood. I can preserve its energies in an arcane matrix for your trip back...", sourceObjectiveStatus = "unverified-source-field" }
quests[30110] = { id = 30110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Finder (1st)" }
quests[30111] = { id = 30111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Finder (Nth)" }
quests[30112] = { id = 30112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Score to Settle", description = "Utgarde's forces are organizing under the advisory of Prince Keleseth, a san'layn ambassador of the Scourge.\n\nWe cannot allow the vrykul to benefit from his counsel any further. Silence him.", sourceObjective = "Dark Ranger Marrah wants you to slay Prince Keleseth inside Utgarde Keep.", completion = "Revenge feels good.  To think that this is but a taste of what's to come.\n\nArthas will get what he deserves soon enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[30113] = { id = 30113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in the Depths", description = "<Zazzo performs an enchantment on the vial of blood, then quickly hands it back to you, as though it's toxic.>\n\nDone! You'll want to get this back to Wrathion as soon as possible, along with those two daggers of yours.\n\nI don't know what he plans to do with this stuff. Between you and me, sometimes that little dragon kid creeps me out. Good luck!", sourceObjective = "Take the Vial of Preserved Dragonsblood, along with your daggers Fear and Vengeance, to Wrathion at Ravenholdt Manor in Hillsbrad Foothills.", progress = "Ah, you've returned! I no longer sense Nalice's presence. Is she dead? Or has she somehow eluded us both?", completion = "You are, indeed, a master of your craft. Nalice is dead, and it is time you are rewarded for your efforts.\n\n<Wrathion takes the vial from you, his face a mask of equal parts reverence and revulsion. He drops the gems you collected one-by-one into the blood, muttering an incantation.>\n\n<Without warning he pours the blood over the blades of the daggers, and the steel seems to writhe and twist as though alive. When the smoke clears, the daggers have altered their shape.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30116] = { id = 30116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharpening Your Fangs", description = "Do you understand why I have you assassinate the dragons, yet spare the mortals? It isn't their fault. They must seek out their own destiny, free from the meddling of my kind.\n\nWe are nearing the end of our mission, and it is time for you to seek out your own destiny as well. I can continue to augment your weapons, but collecting shadowy gems won't be enough. My work will require entire clusters. Gather them from my father's minions...", sourceObjective = "Collect 60 Elementium Gem Clusters from creatures in the Dragon Soul Raid encounter.", progress = "How many clusters have you acquired?\n\nThe tenacity of your race continues to inspire me!", completion = "You have done it! No doubt you placed yourself and your allies in great peril to acquire these. Your sacrifices will be rewarded in time. I will use these as the foundation of a powerful enchantment for you.\n\nBut we will need one additional catalyst. Are you ready for your final and most dangerous mission, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[30117] = { id = 30117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoneplow Thirsts", description = "Excuse me... {name}? Did I hear your name correctly?\n\nI've come from Stoneplow, in the west. They sent me to pick up some emergency beer rations, but the Stormstout Brewery is all boarded up!\n\nIt looks like your handsome friend there - no, not Mudmug, the other one - has a few casks with him. Could you spare a keg for a town in need?", sourceObjective = "Deliver a cask of The Emperor to Loon Mai at Stoneplow in the Valley of the Four Winds.", progress = "Greetings, {class}.", completion = "Finally! Emmi's come through.\n\nI hope all is well at the Stormstout Brewery. My men don't do well without beer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30118] = { id = 30118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patricide", description = "Your next target has claimed the lives of all of my other assassins. I need you to kill my father himself.\n\nYou must destroy Deathwing.\n\nWe are out of time. His madness has already corrupted all the others of my kind, and his darkness will consume the world if he is not stopped.\n\nIf you by some miracle succeed, and can retrieve for me a piece of him - perhaps a fragment of the armor he uses to disguise his true chaotic nature - the reward I give you will be without equal.", sourceObjective = "Destroy Deathwing and retrieve a Fragment of Deathwing's Jaw.", progress = "What of my father?", completion = "I can feel it - like a dark shadow lifted from the land. Dead. My father is dead!\n\n<Wrathion takes the jaw fragment from you. His hands and face blur as he recites a dark enchantment, the gem clusters you collected earlier orbiting around his head. The jawpiece suddenly shatters, and with a terrible hissing sound your twin daggers awaken.>\n\nYour reward is ready. Take them, quickly. You will need them momentarily...", sourceObjectiveStatus = "unverified-source-field" }
quests[30120] = { id = 30120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Drak'Tharon", description = "'Ey, mon, you be here! Dis is good, mon!\n\nDrak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. In return for your help, the keep's most valuable treasures be yours, mon!\n\nOnce ya be reachin' its top, ya must summon me, and I'll perform the ritual.\n\nAlas, my summonin' will be comin' at a cost. Ya must collect mojo from the survivors.", sourceObjective = "Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo.\n\nProvided item:", completion = "We done a great thing, mon! And dis just be da beginning....\n\nSeek me out in Zul'Drak when da time be right.\n\nDere be a war to be won, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[30121] = { id = 30121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search Party", description = "I sent a diplomat to look for allies in the ruins east of here.\n\nMy diplomat has not returned and now Kang tells me this jungle is filled with a sinister people known as the mogu.\n\nChezin is my friend and Leza's brother. To lose a brother would cause her to give in to despair. She already has enough to worry about with her fever.\n\nCould you investigate the ruins east of here and find out what happened?", sourceObjective = "Search the Krasari Ruins for Chezin Dawnchaser.", completion = "P... poison. Need... warn... Dezco...", sourceObjectiveStatus = "unverified-source-field" }
quests[30122] = { id = 30122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Filigree Flask", description = "You have found a beautiful silver flask decorated with ornate filigree.  With the right materials and your skill in alchemy, it could become quite magical.", sourceObjective = "Fill the vial with a potent alchemical mixture.", sourceObjectiveStatus = "unverified-source-field" }
quests[30123] = { id = 30123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skitterer Stew", description = "Leza has a fever. No mother in labor should have a fever.\n\nMama Bramblestaff once told me that Skitterer Stew could heal almost any illness. Let us put this knowledge to the test.\n\nGather some intact skitterer glands for me while I get the herbs we'll need and I'll whip up a batch.", sourceObjective = "Gather 5 Intact Skitterer Glands.", progress = "Even the jungle air is alive with danger.", completion = "Excellent! Nothing clears a sickness like Skitterer Stew.\n\nHere, take this. It's a little memento of Mama Bramblestaff.", sourceObjectiveStatus = "unverified-source-field" }
quests[30124] = { id = 30124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Them!", sourceObjective = "Kill the Darnassian Outrider.", progress = "Sentinels. Bah! I remember a time when these creatures were the terror of the trees, hunting any {race} or tauren that dared enter their wood in search of food or shelter.", completion = "Well done, {name}. You have performed admirably and bought us some time to fortify our defenses. Now if I can just get Dezco to go on the offensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[30127] = { id = 30127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat from Dojan", description = "Mogu? They seem like the elves, ancient and an over developed sense of entitlement. Everyone of Azeroth must learn, sooner or later, that the Horde is not \"visiting\" this world. We are here. We are staying.\n\nTeach them this lesson. Quell their numbers in the ruins south and west of here. Break their amassing forces before they decide to attack.\n\nLearn what you can of how these creatures fight, and how they die.", sourceObjective = "Kill 6 Dojani Reclaimers and 8 Dojani Surveyors, and 4 Dojani Enforcers.", completion = "These are more than just a bandit threat. They are an ancient people beginning to rally under a single banner. Mark my words, soon these lands will know war.", sourceObjectiveStatus = "unverified-source-field" }
quests[30128] = { id = 30128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pools of Youth", description = "The mogu found the Pools of Youth!\n\nMama Bramblestaff used to tell me old stories about those. During the mogu empire they would use the waters to extend life.\n\nThing is those stories never ended well for some reason. As if the waters were cursed.\n\nEither way, we should investigate. There is a good chance those waters might help Leza.\n\nIt looks like the Pools of Youth are on the northwestern side of the ruins.", sourceObjective = "Recover water from the Pools of Youth.", progress = "Leza's pain is immense. Only powers beyond my own can save her and the baby now.", completion = "At this point I am willing to try anything. This land is claiming my wife and unborn child. I need all the help I can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[30129] = { id = 30129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mogu Agenda", description = "Mogu don't often gather in numbers like this. We should find out what they are up to.\n\nI thought I heard someone shouting orders near the center of the ruins.\n\nWe should probably see if he has information.", sourceObjective = "Recover the Dojani Orders.", progress = "The mogu once ruled as emperors, subjugating all races they encountered.\n\nIt would seem these particular mogu have aspirations of reliving the past.", completion = "Wait. This document talks about the Pools of Youth!\n\nThe pools exist?!", sourceObjectiveStatus = "unverified-source-field" }
quests[30130] = { id = 30130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herbal Remedies", sourceObjective = "Find 20 Imperial Lotus Leaves.", progress = "I've been punched, stabbed, thrown off of a cliff, hit in the face by someone's mace, hit in the face by my own mace, and fell off the elevator at Thunder Bluff on more than one occasion.\n\nNone of that pain sounds even half as bad as what Leza is going through. I hope this tea helps...", completion = "Thank you hero. Kor is a brave warrior but he lacks compassion at times. Life must come before death, or there will be none of us left when the fighting is done.", sourceObjectiveStatus = "unverified-source-field" }
quests[30131] = { id = 30131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life", description = "My child is coming. I must help as I may.\n\nStay nearby, hero. If my wife and child survive, I would have them look on the face of the one who saved them.", sourceObjective = "Speak with Sunwalker Dezco, and wait for the newborn.", progress = "I pray to An'she that my wife and child survive this journey.", completion = "She... she died. For all the powers the Light has given me, I was unable to save her.\n\nThanks to your help, however... we saved my sons.", sourceObjectiveStatus = "unverified-source-field" }
quests[30132] = { id = 30132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going West", sourceObjective = "Find the Sunwalker Scout near the Crane Temple.", progress = "War. It always comes down to war.", completion = "{name}! Well timed!\n\nWe were laying an ambush for the Alliance in the ruins west of here when the mogu ambushed us. They are using mage portals to call in reinforcements.", sourceObjectiveStatus = "unverified-source-field" }
quests[30133] = { id = 30133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Wilds", description = "Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers.\n\nThey should be told of what happened here.\n\nIf you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone north. When you reach the temple, find Koro Mistwalker.", sourceObjective = "Locate the missing Zhu's Watch Courier in the northern area of the Dojani River, then continue on to the Temple of the Red Crane and speak with Koro Mistwalker.", completion = "I see... And the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Watch, I have to implore you to help us deal with them here.", sourceObjectiveStatus = "unverified-source-field" }
quests[30134] = { id = 30134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Things", description = "Welcome to the Order of the Cloud Serpent, {race}. I can see from the spark in your eye that you wish to join the Order.\n\nLet me get a good look at you.\n\n<Elder Anli gently holds your head and gazes at your face.>\n\nHmm. I see honesty and earnestness in your heart. You have journeyed far to come here, but I am afraid you must go yet further.\n\nYour path into the Order begins now.\n\nSpeak to Instructor Tong at Windward Isle to the northeast to take the first step.", sourceObjective = "Find Instructor Tong at Windward Isle in the Jade Forest.", completion = "Thank goodness, they finally sent someone!\n\nThings have gotten out of control!", sourceObjectiveStatus = "unverified-source-field" }
quests[30135] = { id = 30135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating the Odds", description = "At first, the Slitherscale were too frightened to approach the wild serpents.\n\nThen, I caught them snatching the eggs under the cover of night.\n\nNow, they are slaughtering adults and hatchlings alike!\n\nIf we do not do something, these gentle creatures will be completely wiped out. Then there won't even be an Order of the Cloud Serpent to join!\n\nGo and slay these vile Slitherscales, and then we will talk.", sourceObjective = "Kill 8 Slitherscale Rippers or Slitherscale Eggdrinkers.", progress = "The Order rarely meddles with the natural balance on this island, but it is too important to save the serpents.", completion = "Thank you, {race}.\n\nI tried to stop the Slitherscale where I could, but I was no match for their numbers.\n\nYour work today will help preserve an entire generation of cloud serpents.", sourceObjectiveStatus = "unverified-source-field" }
quests[30136] = { id = 30136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empty Nests", description = "When the attacks began, the young hatchlings scattered in terror.\n\nThey are roaming around the island, lost and scared.\n\nIf you want to help, take this rope and leash the lost little ones. Take them back to their nests. Return them home.", sourceObjective = "Leash and return 6 Windward Hatchlings to their nests.", progress = "Did you return the hatchlings to their nests?", completion = "Don't worry. The hatchlings will be safe inside their nests.\n\nI can't thank you enough for arriving when you did.", sourceObjectiveStatus = "unverified-source-field" }
quests[30137] = { id = 30137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Collection", description = "Ahhh, I should have known! You have the look of a hungry initiate.\n\nI would gladly help you choose a serpent egg, but the Slitherscale have thoroughly raided the cloud serpent nests.\n\nI'm terribly sorry. I don't know what to tell you.\n\nUnless you're crazy enough to sneak into the saurok camp to the east and retrieve some stolen cloud serpent eggs, I'm afraid I can't help you.", sourceObjective = "Collect 6 Serpent Eggs.", progress = "The saurok keep the stolen serpent eggs in their camp.", completion = "Oh, wonderful!\n\nThese eggs look...well...they look a little on the small side. Are you sure you couldn't find any better ones?\n\nOh well, I suppose with the current situation, we can't be so picky.", sourceObjectiveStatus = "unverified-source-field" }
quests[30138] = { id = 30138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choosing the One", description = "I have examined each egg, {name}. Out of the lot that you brought me, I have chosen the three eggs with the most promise.\n\nYou may choose only one egg to take with you. Are you ready to make your final selection?", sourceObjective = "Speak to Instructor Tong at Windward Isle in the Jade Forest.", completion = "You may choose only one egg to take with you.\n\nChoose carefully. There is no going back.", sourceObjectiveStatus = "unverified-source-field" }
quests[30139] = { id = 30139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", sourceObjective = "Return to Instructor Skythorn at the Arboretum in the Jade Forest.", progress = "The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", completion = "Ah yes, Elder Anli mentioned that a new student had joined our ranks. I see you have already chosen your cloud serpent egg.\n\nI will instruct you on its care. Let me see it for a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[30140] = { id = 30140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", sourceObjective = "Return to Instructor Skythorn at the Arboretum in the Jade Forest.", progress = "The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", completion = "Ah yes, Elder Anli mentioned that a new student had joined our ranks. I see you have already chosen your cloud serpent egg.\n\nI will instruct you on its care. Let me see it for a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[30141] = { id = 30141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", sourceObjective = "Return to Instructor Skythorn at the Arboretum in the Jade Forest.", progress = "The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", completion = "Ah yes, Elder Anli mentioned that a new student had joined our ranks. I see you have already chosen your cloud serpent egg.\n\nI will instruct you on its care. Let me see it for a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[30142] = { id = 30142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's A...", description = "Oh my! This egg is going to hatch at any second!\n\nWell, looks like this little guy is eager to meet you.\n\nAre you ready?", sourceObjective = "Watch your egg hatch.", progress = "What a proud moment for you!", completion = "Congratulations! It's a beautiful hatchling of your own.\n\nPlease take care of it, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30143] = { id = 30143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Grow Like Weeds", description = "Ahh, it is you again, {name}.\n\nInstructor Windblade is looking for you. You can find her on the ridge to the east.\n\nShe has some news about your cloud serpent.", sourceObjective = "Speak to Instructor Windblade at The Arboretum.", progress = "You are doing well, trainee.", completion = "Congratulations, {name}.\n\nThere is great joy in seeing the fruits of your own labor.", sourceObjectiveStatus = "unverified-source-field" }
quests[30144] = { id = 30144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training: Ring Round-Up", description = "Now that your serpent is fully grown, you are ready to begin flight training.\n\nAs with all novices, you must start at the beginning.\n\nYour first task is simple. Fly through 6 of the cloud rings between the spires to the east.", sourceObjective = "Fly through 6 cloud rings while riding your cloud serpent.", progress = "How did your first flight go?", completion = "What have you learned from this lesson?\n\nSpeed. It's all about speed.", sourceObjectiveStatus = "unverified-source-field" }
quests[30145] = { id = 30145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training: Full Speed Ahead", description = "The next task will be a little harder.\n\nAre you ready?", sourceObjective = "Follow Instructor Windblade.", completion = "You did better than I expected. Not bad for a new trainee.", sourceObjectiveStatus = "unverified-source-field" }
quests[30146] = { id = 30146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snack Time", description = "Cloud serpents love to eat, and one of their favorite treats is the sugar minnow.\n\nThese fish can be found in salt or fresh water anywhere in Pandaria. I trust you have some skill in fishing, and your own fishing pole to catch them?\n\nBring me a fresh catch and I'm sure the hungry beasts around here will be very grateful.", sourceObjective = "Fish 10 Sugar Minnow from any fresh or salt water in Pandaria.", progress = "Did you find a good place to fish?", completion = "Oh wonderful! These fish will do nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[30147] = { id = 30147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of the Past", description = "The Order of the Cloud Serpent's history stretches back thousands of years, and although we have tried to preserve the old ways, there are ancient techniques that have been lost over time.\n\nYou can help us recover some of this knowledge by searching Pandaria's dig sites for clues to our past.\n\nUse your archaeology skill to survey around Pandaria and bring me whatever you find.", sourceObjective = "Visit archaeology dig sites around Pandaria and use your survey ability to retrieve 6 Serpentrider Relics.", progress = "How did the excavation go?", completion = "Amazing, {name}. These relics are invaluable to our studies. We will learn much from these fragments.", sourceObjectiveStatus = "unverified-source-field" }
quests[30148] = { id = 30148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Flesh Wound", description = "Many of the baby hatchlings at Windward Isle have been injured as a result of all the fighting.\n\nI have been told that you may be skilled in the art of first aid.\n\nPlease go northeast and use some of your best bandages to save the injured hatchlings.", sourceObjective = "Use Windwool Bandages or Heavy Windwool Bandages to heal 8 Injured Hatchlings at Windward Isle.", progress = "What is your report of the situation at Windward Isle?", completion = "Wonderful! It is a good thing you are trained in the arts of first aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[30149] = { id = 30149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Feast for the Senses", description = "I have heard that you know a thing or two about cooking.\n\nAs it so happens, serpents love to eat Fish Cakes.\n\nIf you use your culinary skills and bring me 5 of these dishes, the cloud serpents around here will be very happy.", sourceObjective = "Collect 5 Fish Cakes.", progress = "Were you able to find the necessary ingredients?", completion = "Oh these do look quite delicious. You are quite the cook!", sourceObjectiveStatus = "unverified-source-field" }
quests[30150] = { id = 30150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet as Honey", description = "<The hatchling scampers about, then whines and whimpers.>\n\nFrom the cloud serpent's behavior, you have a hunch that it wants a sweet treat.\n\nThe fragrant trees in The Arboretum are home to many honey hives.\n\nIt will be a simple matter to collect combs from the nearby honeykeepers.", sourceObjective = "Collect 30 Honeycomb from Angry Honeykeepers in The Arboretum.", progress = "<The hatchling spins around in glee as you return.>", completion = "The hatchling leaps for your hand. It winds its long, serpentine tail around you and begins to lick the honey from your fingers.\n\nThat tickles!", sourceObjectiveStatus = "unverified-source-field" }
quests[30151] = { id = 30151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch!", description = "<The hatchling looks up at you with a bored, listless expression.>\n\nYou have a feeling the serpent is tired of being cooped up all day.\n\n How about playing a little game of catch?", sourceObjective = "Use the Bouncy Ball. Then, catch and return the ball to your hatchling 8 times.", progress = "<The serpent watches you curiously.>", completion = "Oh my, I see you and your serpent are having a great time! Well done, {name}. Playtime will greatly increase your serpent's mental and physical acuities.", sourceObjectiveStatus = "unverified-source-field" }
quests[30152] = { id = 30152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sky Race", description = "The time for the great race is upon us!\n\nTraverse the course among the spires and pass through the checkered flags on each of the 10 balloon checkpoints.\n\nMake sure to pass underneath the finish line when you are done.\n\nThe competition will be fierce, but I wish you luck. Speak to me when you are ready to begin.", sourceObjective = "Complete the Sky Race by flying through 10 checkpoints, then passing underneath the Finish Line at The Arboretum.", completion = "Wonderful! How does it feel to finish the Sky Race?\n\nYou must be eager to collect your prize!", sourceObjectiveStatus = "unverified-source-field" }
quests[30154] = { id = 30154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Easiest Way To A Serpent's Heart", description = "<The hatchling scowls at you.>\n\nUh-oh, looks like someone is in a bad mood today!\n\nLuckily, you know just the thing that will cheer up the little beast.\n\nCloud serpents love the taste of tiger meat, but the tender flanks can be... challenging... to acquire.\n\nLuckily, you recall there are some fat, juicy tigers to the northwest, on Windward Isle.\n\nSure, you might suffer some scratches and a little mauling, but it's all worth it for your serpent, right?", sourceObjective = "Collect 5 Tiger Flanks.", progress = "Looks like the task is done.", completion = "I see you have been hard at work, gathering food for your hungry little serpent. Well done. It may not seem worth it now, but your serpent will know of your efforts, and it will love you for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[30155] = { id = 30155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring the Balance", description = "The situation at the islands remains dire, {name}.\n\nThe Slitherscale saurok have not responded to our attempts at peace, so only one option remains.\n\nIn order to protect the wild cloud serpents, we must rid the island of their presence. Only then can the cloud serpents be left to live in peace.", sourceObjective = "Kill 8 Slitherscale Rippers or Slitherscale Eggdrinkers.", progress = "The poachers will wipe out the cloud serpents completely if they are not stopped.", completion = "If the poachers will not listen to diplomacy, then they will surely listen to our blades. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30156] = { id = 30156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding Time", description = "<The serpent darts forward and bites your fingers.>\n\nOuch! It seems, without a doubt, that the little beast is hungry. You recall that some meaty-looking turtles can be found on the wild cloud serpent island to the northeast.\n\nPerhaps some turtle meat will fill the hatchling's voracious appetite.", sourceObjective = "Collect 3 Saltback Meat and feed them to your hatchling companion.", progress = "<The serpent looks at you with hungry eyes.>", completion = "You are learning well, young trainer. Saltback meat is tough, but loaded with the nutrients that a young hatchling needs to grow.", sourceObjectiveStatus = "unverified-source-field" }
quests[30157] = { id = 30157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emptier Nests", description = "Oh, thank goodness, another cloud serpent trainer!\n\nI just received word that the wild hatchlings at Windward Isle to the northeast are in serious trouble!\n\nWhile the adults fight those terrible saurok, who is watching the cute little babies? No one, that's who!\n\nWE HAVE TO SAVE THEM!\n\nI'm sending every trainer I can find to go and help. If you aren't too busy, can you make sure the hatchlings are safely delivered back to their mothers' nests?", sourceObjective = "Leash and return 6 Windward Hatchlings to their nests.", progress = "How can you resist their cute little faces?", completion = "I see you have been taking good care of the young hatchlings out there. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[30158] = { id = 30158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarming the Enemy", description = "If we are to stop the poachers, we need to take more aggressive action.\n\nIf we can remove the enemies' primary tools for killing and capturing serpents, we may be able to stop their operation altogether.\n\nI need you to go into their territory on the eastern end of Windward Isle and steal their weapons.\n\nA cat without claws cannot strike.", sourceObjective = "Collect 5 Slitherscale Harpoons.", progress = "Is it done?", completion = "We have weakened them, but we cannot celebrate completely. A toothless tiger still has claws.", sourceObjectiveStatus = "unverified-source-field" }
quests[30159] = { id = 30159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preservation", description = "Oh no! We must stop them! {name}, is it? The Order needs your help!\n\nDo you know what those horrible Slitherscale saurok are doing?\n\nThey have the audacity to steal cloud serpent eggs straight from the matriarch's nests!\n\nWhile the cloud serpents become ever rarer, those brutes are... are...\n\n<Suchi takes a deep breath.>\n\n...they're eat their eggs for dinner! It's horrible!\n\nGo to Windward Isle to the northeast and recover any unbroken eggs that you can. As students of the Order, it's our duty!", sourceObjective = "Collect 8 Stolen Eggs.", progress = "Will those nasty Slitherscale saurok never give up?", completion = "Well done, {name}. As soon as Suchi told me she sent you to recover the stolen eggs, I knew you would accomplish the task.\n\nOur instructors will make sure to return these eggs to a safer place.", sourceObjectiveStatus = "unverified-source-field" }
quests[30160] = { id = 30160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Ella", progress = "Why {name}, it's nice to see you again.", completion = "Oh, is this for me? I-I don't know what to say.\n\nIt's very pretty, thank you!" }
quests[30163] = { id = 30163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Tribe", description = "We fell back to the refuge when the mogu attacked but lost a number of our people along the way.\n\nTravel west and north of here and look for any captives you can rescue that could help us in our fight.\n\nLeave any Alliance you find to their fate.", sourceObjective = "Rescue 8 Dawnchaser Captives.", completion = "We've already lost so many. I refuse to lose any more.", sourceObjectiveStatus = "unverified-source-field" }
quests[30164] = { id = 30164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stoneplow Convoy", description = "I tried to save as many of the Stoneplow envoys as I could but these \"mantid\" dragged many of them off into the jungle.\n\nThese are civilians in need of our help.\n\nPlease take the herbs you gathered earlier. I've infused them with what gifts of the Light are still granted me. Use them on as many of the Stoneplow envoys as you can.", sourceObjective = "Use Imperial Lotus Poultice on 7 Stoneplow Envoys.", progress = "A sunwalker's first duty is to preserve and protect life.", completion = "The civilians are trickling in thanks to you. These \"mantid\" creatures are a serious threat. We will need to rally our forces soon to help.\n\nOne of the envoys asked me to give this to you as a token of thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[30168] = { id = 30168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Raiders", description = "Saurok!\n\nThese vile creatures are obsessed with killing and stealing. They attacked our settlement without provocation or warning.\n\nPlease, {class}, can you aid us?\n\nHelp us recover our lost possessions from these Riverblade raiders that march along the river and we will gladly reward you.", sourceObjective = "Recover 5 pieces of Pillaged Jinyu Loot.", progress = "I think they even stole my holy spittoon.", completion = "Not many would stop to help a village in need... especially so deep in the wilds.\n\nYou are a champion to our people, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30169] = { id = 30169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Leader Slovan", description = "The raiders are led by a particularly violent saurok known as Slovan. The Crane Temple usually comes to our aid when he attacks but now we find ourselves outmatched and outmaneuvered.\n\nPlease, {class}, aid us by destroying this raid leader.\n\nYou can find him in his den behind the Krasari Falls.", sourceObjective = "Kill Slovan.", progress = "Slovan has always been a nuisance, but with the Crane Temple's defenses down he has become a true threat.", completion = "You have done us a great service today. On behalf of my people I thank you.\n\nPlease, accept this token of our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[30172] = { id = 30172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barreling Along", description = "No, no, no, don't you worry about pickin' 'em up. I can hold these here barrels.\n\nI may not be the handsomest pandaren, or the smartest, or any fun to be around in the slightest, but I'm stronger than a mushan beast.\n\nI'mma just need you to lead the way.", sourceObjective = "Lead Mudmug back to Halfhill.\n\nIf you become separated from Mudmug, you can find him next to the giant banana in the Gilded Fan.", progress = "Where's Mudmug?", completion = "Good! The water's here!", sourceObjectiveStatus = "unverified-source-field" }
quests[30173] = { id = 30173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Pigs!" }
quests[30174] = { id = 30174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Family", description = "Kor should have caught up by now. He said he was going to secure the Ruins of Korja east of here and meet us to help with the mantid threat.\n\nHe may need help against Groundbreaker Brojai. Could you assist him? Kang and I will follow shortly.", sourceObjective = "Search for Kor Bloodtusk.", progress = "This land claims so much.", completion = "I thank you for avenging my friend, {name}. We did not always see eye to eye, but I will mourn him.\n\nI know he would have wanted you to carry one of his items with you as a token of his memory and gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[30175] = { id = 30175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mantid", description = "The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that.\n\nNow they are preparing to hit Stoneplow.\n\nPlease, {class}, destroy some of these beasts before they get sufficient numbers to flank our home.\n\nIf my cousin, Ambassador Len, is still alive and at our convoy he should be able to reward you for your help.", sourceObjective = "Kill 10 Ik'thik Precursors.", completion = "Thank you for your help, {class}! I've never seen anybody stand up to the mantid like that before.\n\nWell, other than the Shado-Pan, of course...", sourceObjectiveStatus = "unverified-source-field" }
quests[30177] = { id = 30177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Heroic Random (1st) (Cataclysm)" }
quests[30178] = { id = 30178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Wilds", description = "Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers.\n\nThey should be told of what happened here.\n\nIf you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone south. When you reach the temple, find Koro Mistwalker.", sourceObjective = "Locate the missing Zhu's Watch Courier in the southern area of the Dojani River, then continue on to the Temple of the Red Crane and speak with Koro Mistwalker.", completion = "I see... And the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Watch, I have to implore you to help us deal with them here.", sourceObjectiveStatus = "unverified-source-field" }
quests[30179] = { id = 30179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poisoned!", description = "The... mogu. Do not trust. Poison. Get sample... sample blades. Bring to Dezco... in Thunder Cleft, west of here.", sourceObjective = "Gather 5 Mogu Poisoned Blades.", progress = "You have news of Chezin?", completion = "Chezin is dead? This is very bad news indeed. Kor, Chezin and I have fought dragons, undead, and Alliance on nearly every shore that has a name.\n\nTo lose him like this...\n\nThank you for recovering these weapons. It should teach us much about our new enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[30181] = { id = 30181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushan Mastery", description = "Mushan! Would ya look at the size o' 'em. Old as the dirt they walk on probably. A fine trophy.\n\nIf you are lookin' to test your mettle as a big game hunter, start with them.", sourceObjective = "Kill 15 Dustback Mushans.", progress = "They didn't send ya' runin' did they?", completion = "Well done {name}.\n\nMy father travels across the sea to a new continent and all he can seem ta' want to hunt is old borin' wolves.\n\nMe, I like to hunt stuff with meat on its bones.", sourceObjectiveStatus = "unverified-source-field" }
quests[30182] = { id = 30182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fox Mastery", description = "So, when I was scouting east of here I saw a collection of foxes. That's what I first learned to hunt when back on the Wandering Isle.\n\nIf you want to see the challenge a young pandaren hunter faced when growing up, head east and face off against a bunch of foxes. They tend to be clever and cunning so be on your guard.", sourceObjective = "Kill 15 Sly Foxes.", progress = "I used to go on fox hunts with my father. If he could see me now! Hunting in Pandaria!", completion = "Well done! You outfoxed the foxes. I will talk to Mr. Pleeb about getting you another trophy made.", sourceObjectiveStatus = "unverified-source-field" }
quests[30183] = { id = 30183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalker Mastery", description = "Tigers! No matter what land I go to I hear about these big fanged beasts. And yet I haven't had a chance to hunt any of them.\n\nLet's go hunt some tigers. I'll go east, you go west. I think I saw some near Dustback Gorge. I'm sure there are tons near those mushan.", sourceObjective = "Kill 15 Gorge Stalkers.", progress = "What's your count up to?", completion = "Wow! You really racked up a count. I'll chat with Mr. Pleeb about getting the best one converted to a trophy for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30184] = { id = 30184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushan Mastery: Darkhide", description = "My boy here is a talented hunter... in training. Let's show him an old 'Nessy style hunt shall we?\n\nI saw a mighty big mushan east of here with a hide dark as night. It looked like it had taken down a number of hunters in its day.\n\nIf you want a big game hunt, go try an' take it on.", sourceObjective = "Obtain Darkhide's Head.", progress = "Puttin' the \"big\" into \"Big Game Hunter.\"", completion = "Now that's a proper trophy right there.", sourceObjectiveStatus = "unverified-source-field" }
quests[30185] = { id = 30185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortoise Mastery", description = "Granted, tortoises are not big game but they can be mean game. They also work as the perfect bait for bigger game!\n\nGotcher found some ol' tablets sayin' that the Torjari Pit is a sacrificin' site. The old empire used ta' feed unruly sorts to the waters as it were.\n\nWell ah mean to see me what's down in that water. Gather up some fresh tortoise shells and meet me at the pit.\n\nLet's see if ol' legends be true.", sourceObjective = "Gather 5 Intact Tortoise Shells.", progress = "I've always been livin' in me father's shadow. But after today, folks are gonna remember the name of Nesingwary, Jr.!", completion = "Thank ye. This one aught ta' one up me pop.", sourceObjectiveStatus = "unverified-source-field" }
quests[30186] = { id = 30186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parental Mastery", description = "If them tablets were correct, all ay got ta do is a small dance ritual and the big thing o' the deep will be summoned.\n\nWhen it comes out, we'll get 'em and show me pop we are both true big game hunters like him.", sourceObjective = "Destroy Torjar's Bane.", progress = "Now that is how ya big game hunt.", completion = "You saved me son! I canno' ever thank ye enough. Please! Take this fer your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[30187] = { id = 30187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training: In Due Course", description = "Now that you have learned the basics of the race, you should go learn the course.\n\nExplore the spires and collect a race flag from each of the checkpoints.\n\nFly through each checkered flag to collect it.", sourceObjective = "Fly through 10 Race Flags at the Checkpoints floating above the Mistveil Sea.", progress = "Do you have what it takes to compete... and win?", completion = "Well done. If you hadn't been capable of finding the checkpoints, I fear you would never have done well in the Sky Race.", sourceObjectiveStatus = "unverified-source-field" }
quests[30188] = { id = 30188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Skies", description = "I can no longer call myself your teacher, {name}.\n\nYou have proven yourself worthy of your cloud serpent.\n\nToday, you shall join our ranks. Are you ready?", sourceObjective = "Join the Order of the Cloud Serpent.", completion = "Today, we become brethren. Congratulations on joining the Order of the Cloud Serpent. Let us ride together!", sourceObjectiveStatus = "unverified-source-field" }
quests[30189] = { id = 30189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Ella", progress = "How are you today, {name}?", completion = "Really? For me?\n\nSuch a lovely apple shouldn't be eaten alone.\n\nHere, please have half." }
quests[30190] = { id = 30190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprite Plight", description = "Sprites again! I hate these things. We need to stop them before they hurt someone or burn down half of the village!\n\nIf you see any of the pests, please deal with them!", sourceObjective = "Kill 8 Slateskin Troublemakers.", completion = "We need to figure out where these things are coming from. We're dealing with this near daily and it's getting out of hand.\n\nThank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[30191] = { id = 30191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steer Clear of the Beer Here", description = "Someone left some beer out up on the southern rise and now the sprites have developed a taste for our brew. They've been sneaking into town all morning, stealing whatever kegs they find.\n\nBring back what you can. A pandaren worker without brew is just... it won't be very productive. We need the men in good spirits.", sourceObjective = "Recover 10 Stolen Mistfall Kegs.", progress = "Did you find any of the stolen kegs?", completion = "The workers will love you for this!", sourceObjectiveStatus = "unverified-source-field" }
quests[30192] = { id = 30192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Town, It's on Fire", description = "I don't know if you noticed, but my town is burning...\n\nThe sprites have started kicking the braziers! They're going to set fire to the whole town!\n\nPlease help us! Stamp out any fires you see!", sourceObjective = "Put out 30 Brazier Fires.", progress = "I'm at my wit's end...", completion = "It's a relief that you're here to help. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30193] = { id = 30193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meating Expectations", description = "Hard workers deserve hearty meals, but I'm all out of good meat!\n\nCan you head out into the forest and get me some fresh gazelle meat?", sourceObjective = "Retrieve 10 slabs of Fairlands Gazelle Meat.", progress = "No shortage of mouths to feed, that's for sure!", completion = "Doesn't get much fresher! Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30194] = { id = 30194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Storm", description = "The villagers have lost another yak this morning to one of the thundermaw wolves from across the river. The wolves grow bold.\n\nThis is a sign that they are breeding beyond the vale's ability to sustain them. It's time to thin their numbers again.\n\nIf you are willing to aid me in this, you would have my sincere appreciation.", sourceObjective = "Kill 8 Thundermaw Wolves.", progress = "It is upon us to not diminish the gazelle in the forest too greatly, or it will be upon us that the wolves come to our doorstep seeking new food.", completion = "Your act is one of a responsible hunter. I respect you for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[30195] = { id = 30195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blooming Blossoms", description = "Would you do a humble merchant a favor? I've been needin' to refresh my stock of eternal blossoms. They grow in the woods nearby.\n\nCould you help me out, perhaps?", sourceObjective = "Collect 10 Eternal Blossoms.", progress = "Was your flower-gathering bountiful?", completion = "Aha! You are quite the kind patron.\n\nThank you... thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30196] = { id = 30196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lushroom Rush", description = "Building a new village makes for hungry workers it seems!\n\nI have a hearty stew recipe prepared, but I need some lushrooms from the Tu Shen Burial Ground to the east. Apparently there are roused spirits causing trouble up there though, and I'm not very well suited for the violent life.\n\nIf you're heading up the burial grounds today, could you collect some lushrooms for me?", sourceObjective = "Collect 12 Lushrooms.", progress = "I can hear the hungry bellies rumbling throughout the village!", completion = "Good timing! The stew's almost ready.\n\nYou have my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[30197] = { id = 30197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cart Ride", description = "The vale has been quiet all morning. I'm sending Rook with a cart of supplies out to the XXX Village. You should join him.", sourceObjective = "Ride a delivery cart to XXX Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[30200] = { id = 30200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Ashen Webs", description = "We used to have the trainees clear out the ruins of spiders as part of their training, but now we send them straight to the mogu front. The spiders have gotten out of control.\n\nCare to put things back in control?", sourceObjective = "Kill 8 Ashweb Spiders.", completion = "You're quicker than the trainees, but I would have been disappointed if you weren't. Thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[30204] = { id = 30204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Not a Rock!", description = "Okay, these spiders are seriously creeping me out. Especially those egg sacs they leave lying around that I keep accidentally stepping on only to be covered in very little but very creepy spiderlings. Ug, makes me shudder just thinking about it.\n\nI say you burn them. Burn them all.", sourceObjective = "Kill 50 Ashweb Spiderlings. Use Kun's torch to burn them inside their pods.", completion = "Thank you. I'd say I have about a week of Anji making fun of me for the screaming, and then I should be in the clear.", sourceObjectiveStatus = "unverified-source-field" }
quests[30205] = { id = 30205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runelocked", description = "Hello, friend.\n\nOne of Leven's men brought word to me of a mogu artifact in the eastern ruins, but said he couldn't figure out how to retrieve it. I suspect it's guarded by one of their rune locks.\n\nIf you go to the artifact, you should find four runes somewhere nearby that when activated will release the lock. If you could bring the artifact back to me, I would be very grateful.", sourceObjective = "Retrieve the Ancient Mogu Artifact.", progress = "Did you find the runes I was telling you about?", completion = "This is marvelous... very well perserved. Thank you very much, friend! I owe you for this.", sourceObjectiveStatus = "unverified-source-field" }
quests[30206] = { id = 30206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runes in the Ruins", description = "In the walls of the ruins themselves, there are precious runestones that we can make use of back in the eastern vale.\n\nIf you see any while you are within the ruins, would you be so kind as to bring them back to me?", sourceObjective = "Collect 12 Guo-Lai Runestones.", progress = "These runestones were used as sources of power long ago, when the mogu still ruled the vale.", completion = "These are lovely! Thank you, kind {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30225] = { id = 30225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashweb Matriarch", description = "My dear Kun spotted more spiders pouring out of the Guo-Lai Halls this morning, and when he went to investigate, he uncovered another spider matriarch inside.\n\nI need you to kill it.", sourceObjective = "Kill Bloodtip, the Ashweb Matriarch.", progress = "Kun's always had a better eye than me. He says that I get a bit of tunnel vision when I see something that needs to be killed. He's probably right.", completion = "You've got a follow-through I can respect, {class}. Thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[30226] = { id = 30226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood on the Rise", description = "A small group of mogu have been sighted on Ruin's Rise, to the north.\n\nExtinguish them.", sourceObjective = "Kill 8 Shao-Tien mogu on Ruin's Rise.", completion = "As it should be. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30227] = { id = 30227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wulon, the Granite Sentinel", description = "One of the quilen statues in Guo-Lai Halls came to life and nearly killed my precious Kun. I won't have it! No one threatens my Kun.\n\nI want you to go in there and smash the thing to pieces. I'd do it myself, but I need to attend to my lover's wounds first.", sourceObjective = "Kill Wulon, the Granite Sentinel.", progress = "Kun's doing okay. Have you smashed that statue for me yet?", completion = "Thanks. I owe you one, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30228] = { id = 30228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troubling the Troublemakers", description = "The wood sprites are back. I need you to kill them before they cause anymore trouble.", sourceObjective = "Kill 8 Stonebark sprites.", completion = "Some peace and quiet. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30229] = { id = 30229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greater Danger", description = "I apologize for my harsh words earlier. Dezco might have been right to wait and move west with a unified strength.\n\nThe mogu hit us hard when we were searching the ruins west of here. They ambushed us using summoning portals and some dark magics. I haven't seen such evil sorcery used since Outland. \n\nWe need a respite. Head west, kill their summoners, cut their supply line.", sourceObjective = "Kill 8 Korjani Reclaimers.", completion = "With their reinforcements severed we can begin to mount an offensive against their Lord Reclaimer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30230] = { id = 30230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Reclaim", sourceObjective = "Recover 10 Mogu Artifacts.", progress = "Every artifact in our possession is one less weapon in mogu hands.", completion = "Well done {name}. You have removed the sword from the child's hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[30231] = { id = 30231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pomfruit Pickup", description = "I need more pomfruit! Go knock some loose from the trees for me, would you?\n\nTake this, I use it when I go harvesting. Things go quicker when the fruit comes to you!", sourceObjective = "Gather 12 Pomfruit.", progress = "I always misjudge how much juice I can get out of these things.", completion = "Delicious! I am indebted to you, my friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30232] = { id = 30232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruffling Some Feathers", description = "The hawk numbers in the vale are thriving. This is opportune for our fletchers, for we will need a great number of feathers if we are to keep the archers upon the wall stocked with arrows.\n\nIf you would not mind, could you aid us in gathering these feathers?", sourceObjective = "Gather 80 Silken Feathers.", progress = "I hesitate to continually ask such menial things of one so accomplished as you, but we are in desperate times.", completion = "You have my most gracious thanks, young one.", sourceObjectiveStatus = "unverified-source-field" }
quests[30233] = { id = 30233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracklefang", description = "Hi! So, I have a dilemma. I've only got one good wolf name.... wait for it... Cracklefang! I know, amazing right?! But now there are TWO big nasty wolves in the forest, which is all kinds of confusing.\n\nI need you to kill one of them so I can free up the name. Should be simple enough, yeah? Especially for someone of your incredibleness.\n\nSo, are you on board? I'm hoping for yes!", sourceObjective = "Kill Cracklefang.", progress = "Cracklefang. Cracklefang. Every time I say it I get a shudder from all the awesome. I'm really good at this naming thing.", completion = "Yes! Only one Cracklefang remains to terrorize the goats and yaks of the Vale of Eternal Blossoms. As it should be! Thank you for that!\n\nI sure hope no more big nasty wolves turn up. I really don't think I'm going to be able to come up with another name that can live up to that one.", sourceObjectiveStatus = "unverified-source-field" }
quests[30234] = { id = 30234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vicejaw", description = "Vicejaw! Sounds absolutely violent, does it not? I came up with it myself, and I think it's very suiting. I tried to wrestle my staff away from him for hours, but he simply would not let go!\n\nOkay, it was really more like a few seconds. I like to be truthful to my friends, even if it makes my stories significantly more boring.\n\nAnyway, would you be so kind as to release your oh-so-potent wrath upon this crocolisk with a vice-like jaw, and then kindly bring my staff back? Preferably in-tact!", sourceObjective = "Kill Vicejaw and return Ren's Longstaff.", progress = "I all truth, this is not the first crocolisk I have named Vicejaw, or even the eleventh. But it's such a fitting name, who can blame me?", completion = "My staff! My gorgeous staff! We shall never part again. I shall lean on you, and you will always be there. And I promise not to poke crocolisks with you anymore.\n\nThank you, friend. Your staff retrieval skills have proved invaluable today!", sourceObjectiveStatus = "unverified-source-field" }
quests[30235] = { id = 30235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quid Pro Quo", description = "Quid is a very powerful and very ancient water spirit, though you might not know it with his child-like ways.\n\nThis morning, Quid nearly killed several villagers in the bar when he jokingly caused several of the water kegs to explode.\n\nAs long as the water flows, Quid will remain. He cannot be slain. But he can be reminded that we do not take his dangerous antics in jest.\n\nWould you be willing to carry this message to him on behalf of the village?", sourceObjective = "Defeat Quid, the Spirit of the Misty Falls.", progress = "The power of an ancient spirit in the mind of a child is a quite dangerous thing.", completion = "For the sake of the villagers, I hope he remains at bay for some time.\n\nThank you, my friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30236] = { id = 30236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aetha", description = "It seems Aetha has been levitating the livestock and dropping them into the river again. The mayor has requested that we remind her that these kinds of jokes are not welcomed.\n\nWould you be so generous as to travel to the ridge above the village and teach her this lesson? You cannot kill her, you can only send her away for a time, but this should prove a potent reminder.", sourceObjective = "Defeat Aetha, the Spirit of the Golden Winds.", progress = "If Aetha is killed, she will return with time, as the other spirits of the vale do. We need find no guilt in defeating her.", completion = "The spirits may be childlike, but they possess generous mounts of strength for their size. Your victory is no small thing, and is very appreciated.", sourceObjectiveStatus = "unverified-source-field" }
quests[30237] = { id = 30237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pandaren Uprising Relived", description = "In the Tu Shen Burial Ground to the east, the spirits of ancient mogu are locked in battle with the spirits of our pandaren ancestors that rose up against them. The spirits have seen no rest since the return of the mogu to the valley.\n\nIf you would be willing to go to the graveyard and force the mogu to relive their defeat again, we might offer some lasting peace to the spirits of our ancestors.", sourceObjective = "Kill 8 Ancient Mogu Spirits.", progress = "The valley has lost much of its peace and tranquility since the mogu returned and set foot in it. It is a saddening thing.", completion = "The spirits of the pandaren monks seem invigorated by the deaths of their mogu oppressors.  It is a small victory, but it shows respect to great heroes of the past.", sourceObjectiveStatus = "unverified-source-field" }
quests[30238] = { id = 30238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Rest", description = "The spirits of our ancestors are reliving one of the most revered battles in our history at the Tu Shen Burial Grounds to the east.\n\nDo as I ask, {race}, and honor their gravestones. Remind them that they are respected even these many years later, and that they are deserving of peaceful rest.", sourceObjective = "Honor 6 Pandaren Gravestones.", completion = "Thank you, my friend. You respect for our ancestors means a great deal.", sourceObjectiveStatus = "unverified-source-field" }
quests[30239] = { id = 30239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lao-Fe the Slavebinder", description = "You can hear the spirit of Lao-Fe, the Slavebinder shouting taunts from the cave at the top of Tu Shen Burial Mound.\n\nDefeating him will surely serve to ensure victory for the spirits of the pandaren monks.", sourceObjective = "Kill the Spirit of Lao-Fe, the Slavebinder.", progress = "Lao-Fe the Slavebinder was ruthless, even for a mogu. He was one of the first overthrown during the rising of the monks at Tu Shen, and that victory spurred the monks on for the rest of the uprising.", completion = "Lao-Fe the Slavebinder was one of the most spiteful and vicious mogu of his time. May defeating his spirit act as a reminder to all the mogu in the vale of the fate that awaits them if they seek to defile the sacred pools again.\n\nYour strength is unquestionable. You have my respect, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30240] = { id = 30240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival Ring: Flame", description = "This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare.\n\nSurvive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.", sourceObjective = "Enter the Survival Ring and survive for 60 seconds without leaving.", progress = "The constant danger in the ring prepares us for life or death fighting we have to endure outside the wall.", completion = "Not bad, {class}. Not bad at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[30241] = { id = 30241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Stoneplow", description = "So much death. And more to come, if Ambassador Han's stories of the mantid are to be believed.\n\nWe must help. We must do our part to save lives.\n\nTravel to Stoneplow. Warn them of the coming mantid attack.\n\nI will join you with what forces I can muster once I have laid Kor's body to rest.", sourceObjective = "Travel to Stoneplow Village in Valley of the Four Winds.", completion = "Mantid from the south? This is not a good day.", sourceObjectiveStatus = "unverified-source-field" }
quests[30242] = { id = 30242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival Ring: Blades", description = "This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare.\n\nSurvive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.", sourceObjective = "Enter the Survival Ring and survive for 60 seconds without leaving.", progress = "The constant danger in the ring prepares us for life or death fighting we have to endure outside the wall.", completion = "Not bad, {class}. Not bad at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[30243] = { id = 30243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantid Under Fire", description = "The mantid are attacking again, and we're a bit short-handed up on the wall. In hopes that you'd help, I saved one of the more fun posts for you: the hot oil!\n\nIt's a bit more violent and a bit less scandalous than it sounds.\n\nIt's simple really. Get up on the wall, find one of the oil stations, and dump it on any of the mantid pouring up against the wall. It's very effective.", sourceObjective = "Use a Hot Oil Cauldron to kill 80 mantid near the Gate of the Setting Sun.", progress = "The hard part is the cleanup. Fortunately, you're not responsible for that.", completion = "You've done devastating damage to the mantid forces. The wall defenders should be able to get things under control.", sourceObjectiveStatus = "unverified-source-field" }
quests[30244] = { id = 30244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Along the Serpent's Spine", description = "There are mantid on top of the wall. The defenders on the ramparts are calling for help!", sourceObjective = "Kill 10 Krik'thik mantid on the Gate of the Setting Sun.", progress = "What are you doing here? They need you on the wall!", completion = "The mantid forces on the wall have been thinned.", sourceObjectiveStatus = "unverified-source-field" }
quests[30245] = { id = 30245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Scouts", description = "We sent some scouts towards the Five Sisters to the north to try and find whatever mogu leader has risen up to direct their movements in the valley. Few have returned.\n\nI'd like to think they're just off downing too much ale or being irresponsible with some young pandaren, but they may actually be in some trouble.\n\nCan you scout for the scouts? And see if they've turned up any information on that leader while you're at it?", sourceObjective = "Recover 3 Shado-Pan Scout reports.", progress = "Go. Missing scouts. Bad mogu leader. Remember?", completion = "The scout reports have pinpointed the mogu leader's position.", sourceObjectiveStatus = "unverified-source-field" }
quests[30246] = { id = 30246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upon the Ramparts", description = "Some of the mantid have made it on top of the wall. There's some risk they'll route the soldiers we have posted there if their numbers are large enough.\n\nI need you to get on top of the wall and help clear out any that have broken through.", sourceObjective = "Kill 10 Krik'thik mantid on top of the Gate of the Setting Sun.", progress = "We're spread thin defending so many fronts. This is where the best of us shine.", completion = "The mantid forces on the wall have been thinned.", sourceObjectiveStatus = "unverified-source-field" }
quests[30247] = { id = 30247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roll Club: Vale of Eternal Blossoms", description = "Follow the flags. Make the checkpoints. Round the loop. Get back to me before your time is up.\n\nSpeak to me when you're ready to roll.", sourceObjective = "Complete the Vale of Eternal Blossoms roll course.", sourceObjectiveStatus = "unverified-source-field" }
quests[30248] = { id = 30248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Butcher", description = "Scouts reports place the displaced Shao-Tien Imperion at the north end of the wall.\n\nAngi Autumnlight spelled out your goal in no uncertain terms: find this leader and kill him.", sourceObjective = "Kill Bai-Jin the Butcher.", progress = "I've heard that you were passed information regarding the location of the new mogu leader. Did you go all Anji on his arse?", completion = "Look at you! All proactive and assertive. Looks good on you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30249] = { id = 30249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Setting Sun", description = "A giant beast has burrowed under the gate into the courtyard. The defenders need your help!", sourceObjective = "Kill Kri'chon, the Corpse-Reaver.", progress = "They need you in the courtyard!", completion = "I heard you performed some heroics in the courtyard! Your name will be remembered on the wall for some time. Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30251] = { id = 30251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyraxxis, the Krik'thik Swarm-Lord", description = "A giant mantid is terrorizing the inside of the wall. It seems doubtful that the defenders will be able deal with it without you.", sourceObjective = "Kill Vyraxxis, the Krik'thik Swarm-Lord.", progress = "Yes, {class}?", completion = "I like your initiative. Good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[30252] = { id = 30252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Helping Hand", description = "I've been pushing and shoving and hammering all morning, but it's hopeless.\n\nThese rocks won't budge!\n\n\"It will be a breeze,\" Grandpa said. \"Farming's like breathing!\" he said. Maybe for him, but not for me!\n\nHow am I supposed to succeed at this whole FARMING thing if I can't even clear my farm for planting?\n\nHey, wait a minute. You look like you've got some muscle on you.\n\nWould you be willing to help me out? Just until I can catch my breath.", sourceObjective = "Destroy 8 Unbudging Rocks.", progress = "I really wasn't cut out for this type of work. I didn't exactly grow up in the country.", completion = "What? You cleared the rocks? That's great news!\n\nMaybe now I can actually start growing something on this farm!", sourceObjectiveStatus = "unverified-source-field" }
quests[30254] = { id = 30254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow II: Tilling and Planting", description = "Okay, now we've got our seeds, it's time to plant them.\n\nFirst, we have to prepare the soil! You gotta till the soil and break it up to make a nice bed for our little sprouts.\n\nTill those two plots of soil over there, then plant the seeds in them.", sourceObjective = "Till 2 plots of Untilled Soil to create Tilled Soil. Then, use the EZ-Gro Green Cabbage Seeds on 2 plots of Tilled Soil.", progress = "Well, go ahead - bust that soil up and plant the seeds!\n\nYou aren't giving up already are you? I need your help!", completion = "Nicely done.\n\nNotice how those seeds sprouted immediately? That's part of what makes this valley so ideal for farming - something about the soil here just makes veggies grow like crazy!\n\nThe work's not done yet, though.", sourceObjectiveStatus = "unverified-source-field" }
quests[30255] = { id = 30255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow III: Tending Crops", description = "My grandfather used to say \"Yoonie, a cabbage is like a woman: ignore her and she'll turn rotten. Pamper her and she'll grow big and plump and you can put a ribbon on her and take her to market to show her off to your frie-\" look, he was from a different time, okay?\n\nThe point is, now that our cabbages have sprouted, they need attention! Today they look a little dry, so you should water them.\n\nHere's the old watering can grandpa left. It will always be near the field if you need it.", sourceObjective = "Use the Rusty Watering Can to water 2 Parched EZ-Gro Green Cabbages at Sunsong Ranch.", progress = "Come to think of it, grandpa said a lot of really offensive things.\n\nMaybe I should avoid quoting him from now on...", completion = "Great, the cabbages are tended and looking good!\n\nToday they were thirsty, but you never know what they might need. Pay close attention to your crops and tend them accordingly.\n\nI got all kinds of advice from my grandpa, so if you're ever unsure of how to take care of something, feel free to ask!\n\nJust make sure it's strictly related to farming...", sourceObjectiveStatus = "unverified-source-field" }
quests[30256] = { id = 30256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow IV: Harvesting", description = "It's time for our hard work to pay off! Normally we'd have to wait a day before the crops are ready to harvest.\n\nFortunately, those seeds Greenfield gave us were specially designed to grow FAST. The yield won't be worth much, but they're good for stepping new farmers through the process.\n\nOur cabbages should be ready to harvest. I'll let you do the honors, of course!", sourceObjective = "Harvest 2 EZ-Gro Green Cabbages from your field and bring them to Farmer Yoon in Sunsong Ranch.", progress = "Look at those... err, what do they say around here? Oh yeah, b'yoots!\n\nLook at those b'yoots!\n\nI think I'm getting the hang of this farmer thing.", completion = "Well, those are the basics!\n\nTill the soil, plant the seeds, tend to any threats, then wait for the results!\n\nToday was easy, but stay on your toes: my grandfather told me all kinds of crazy stories about farming at Sunsong Ranch.\n\nFarming ain't all giant turnips and roses, you know.", sourceObjectiveStatus = "unverified-source-field" }
quests[30257] = { id = 30257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow V: Halfhill Market", description = "All right friend, all of that farming was just for practice!\n\nAre you ready to try the real thing?\n\nThere's a lady by the name of Gina Mudclaw who runs the Halfhill Market, which is across the street to the south.\n\nI heard she's looking to buy some vegetables. Since it's your first time meeting her, you shouldn't go empty-handed.\n\nWhy don't you look around the ranch and see if there are any items hiding around?\n\nMight be that we'll find a good gift to take to our new neighbor!", sourceObjective = "Investigate the Dark Soil underneath Farmer Yoon's house, then give a gift to Gina Mudclaw at the Halfhill Market.", progress = "Hey, haven't seen your face around here before! What's your name?", completion = "Oh my, a marsh lily!\n\nHow did you know that these are my favorite? I just might take a liking to you, stranger.\n\nThank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[30258] = { id = 30258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mung-Mung's Vote I: A Hozen's Problem", description = "I've been thinkin' about how to get into the Tiller's good graces, {name}.\n\nNow, the Tiller's Union accepts new farmers each year, and there are five members on the voting council.\n\nWe already got Gina's vote, but we'll have to prove ourselves to the other four members of their board.\n\nWhy don't you go over and say hello to Mung-Mung? He works with Mr. Mudclaw out on the Mudclaw's farm to the northwest.", sourceObjective = "Speak to Mung-Mung at Haohan Mudclaw's House in the Valley of the Four Winds.", completion = "Yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[30259] = { id = 30259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mung-Mung's Vote II: Rotten to the Core", description = "Dem virmen's back!\n\nThey been biting Mr. Mudclaw's carrots. Ruining his crop. And who is gonna pay? Mung-Mung, that's who!\n\nYou go get the chewed up carrots before Mr. Mudclaw sees. They all over the fields to the southwest, and down under the ground in the virmen's tunnels, too.\n\nOtherwise, Mung-Mung in big trouble.\n\nYou do this for me?", sourceObjective = "Collect 10 Partially Chewed Carrots.", progress = "I don't see no chewed up carrots. You don't see no chewed up carrots. Mr. Mudclaw never know, okay?", completion = "What do you mean, no virmen chewed them up? Teeth marks too small? WHAT? Then who else do this?", sourceObjectiveStatus = "unverified-source-field" }
quests[30260] = { id = 30260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing the Farm I: The Weeds", description = "Hey {name}, I've been thinkin' recently about expanding my farm.\n\nSee that plot there that's just covered in weeds? If we can get rid of those weeds, we could use that land for planting.\n\nI heard there's a farmer by the name of Gai Lan who knows a thing or two about weed whackin'.\n\nHis farm is just out west. Go talk to him and see if he'd be willing to help us.", sourceObjective = "Speak to Gai Lan at The Heartland in the Valley of the Four Winds.", completion = "Oh yeah, Farmer Yoon. I've seen him around town.\n\nSeems like a nice enough fella.", sourceObjectiveStatus = "unverified-source-field" }
